quests[37728] = { id = 37728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge trinkt mit", description = "Die Eier werden dem Charakter meiner Tränke etwas Pep verleihen. Aber es fehlt noch eine weitere Komponente, und die darf man nicht unterschätzen!\n\nDie Dekoration.\n\nMan könnte natürlich die übliche Olive auf einem Zahnstocher verwenden. Oder einen nachlässig drapierten Karottenstängel.\n\nAber das ist nicht mein Stil.\n\nOh, nein, <mein Freund/meine Liebe>. Was MEIN Trank als Alleinstellungsmerkmal braucht, kommt von einer einzigartigen Kreatur. Ich werde ihn nur ein einziges Mal kredenzen und deswegen muss es etwas Besonderes sein.\n\nWas ich brauche, sind die Augen von Gangamesh.", sourceObjective = "Sammelt die sechs Augen von Gangamesh ein.", progress = "Und? Habt Ihr die Augen?", completion = "Ich wollte dieses Meisterwerk eigentlich einer der Damen des Hofes kredenzen. Dies könnte mein Ansehen in bestimmten gesellschaftlichen Zirkeln beträchtlich verbessern.\n\nAber ich bringe es einfach nicht fertig. Also wer hätte es mehr verdient, meinen Meistertrank zu trinken als... ich selbst?", sourceObjectiveStatus = "unverified-source-field" }
quests[37729] = { id = 37729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stegreifaufgabe: Fortgeschrittenes Runenzeichnen", description = "Ihr seid noch immer wild darauf, in das Studienzimmer der Direktorin zu gelangen, was? Ich denke, ich kann Euch hineinlassen... sofern Ihr mir beweisen könnt, dass Ihr auch gelernt habt.\n\nDie korrekte Runenformung ist für das Zauberwirken von entscheidender Bedeutung. Wenn Ihr eine Rune zeichnen könnt, könnt Ihr auch einen Zauber wirken.\n\nIch werde Euch einen Umriss vorgeben, Ihr könnt dann die Runen einfach abschreiten.", sourceObjective = "Zeichnet eine arkane Rune, eine Feuerrune und eine Frostrune nach.", progress = "Na los! Bewegt Eure Füße!", completion = "Vorbildliche Arbeit, junger {name}. Mit solchen Runen werdet Ihr blitzschnell Euren Abschluss haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37730] = { id = 37730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der Direktorin", description = "Ich habe so eine Ahnung, dass Ihr Eure Studien vernachlässigt. Aber ich sehe, dass Ihr es kaum abwarten könnt, die Direktorin zu treffen.\n\nAlso gut! Die Direktorin Azurmond ist gleich da oben. Aber ich befürchte, dass sie nicht gern gestört wird.", sourceObjective = "Holt den Schlüssel des Gezeitensteingewölbes von Elya Azurmond, der Direktorin der Akademie.", progress = "Habt Ihr Euch mit der Direktorin getroffen?", completion = "Sie... hat Euch den Schlüssel gegeben? Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[37733] = { id = 37733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinz Farondis", description = "Es freut mich, dass meine Zweifel an Euch unbegründet waren.\n\nIhr wünscht, Prinz Farondis zu sprechen? Dann folgt mir. Ich werde Euch zur Halle des Prinzen bringen.", sourceObjective = "Trefft Euch mit Nachtwächterin Idri am Zerfallenen Palast.", completion = "Das ist er... hinter mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[37736] = { id = 37736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleider machen Leute", description = "Moment mal. Wie seht Ihr eigentlich aus?! Als wäret Ihr geradewegs von der Straße hier hereinmarschiert. Wo sind Euer Gewand und Euer Hut?\n\nUnd erzählt mir nicht, Ihr wolltet die Akademie ohne Euren Zauberstab und Euer Zauberbuch betreten.\n\nImmer diese Erstsemester.\n\nSammelt Euren Kram zusammen. Dann werde ich Euch vielleicht Eintritt in die Akademie gewähren.", sourceObjective = "Besorgt Euch Hut, Gewand, Zauberstab und Zauberbuch der Akademie von Nar'thalas.", progress = "Wie ich sehe, versucht Ihr noch immer, in die Akademie zu gelangen.", completion = "Der Hut und das Gewand passen nicht zusammen, aber Ihr seht jetzt besser aus. Ich erkenne Euch ja kaum wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[37749] = { id = 37749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfungen des Khadgar: Eiserne Jungfrauen", description = "Besiegt Eure Feinde mit größeren Fähigkeiten, um Euch Khadgars Gunst – und entsprechend größere Belohnungen – zu sichern!", sourceObjective = "Geht aus der Begegnung mit den Eisernen Jungfrauen unter den folgenden Bedingungen siegreich hervor.", sourceObjectiveStatus = "unverified-source-field" }
quests[37750] = { id = 37750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufe aktiv" }
quests[37751] = { id = 37751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgelder aktiv" }
quests[37752] = { id = 37752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkämpfe aktiv" }
quests[37753] = { id = 37753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktjäger aktiv" }
quests[37754] = { id = 37754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon aktiv" }
quests[37756] = { id = 37756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ummauerte Stadt: Farnspore", description = "Die Eiserne Horde ist nicht die einzige Gefahr, der wir in Draenor gegenüberstehen. Wir müssen uns auch um das Chaos kümmern, das sie hinterlässt.\n\nFarnspore, der urzeitliche Tiefenwanderer, wurde durch die Anwesenheit der Eisernen Horde aus den Gewässern um Hochfels angelockt. Er verbreitet Pilzbewuchs wo er geht und steht und wird uns alle vernichten, wenn wir uns nicht bald um ihn kümmern.\n\nReist nach Hochfels und besiegt Farnspore.", sourceObjective = "Bezwingt Farnspore in Hochfels.", completion = "Gute Arbeit, Boss! Damit ham wir vehindert, dass Farnspores Pilzbewuchs sich weiter in Draenor ausbreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[37757] = { id = 37757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Sanktum: Ko'ragh", description = "Vergesst alles, was Ihr über die Oger in Azeroth wisst, {name}. Die Oger von Draenor waren einst Herrscher über eine mächtige Zivilisation und jetzt stehen sie kurz davor, ihre alt Macht wiederzuerlangen.\n\nBei den Hochfelsausgrabungen in Nagrand wurde ein geheimnisvolles Relikt freigelegt. Der einzige Oger, der den direkten Kontakt mit diesem Relikt überlebt hat, ist Ko'ragh und er ist seitdem fast vollständig immun gegen jede Art von Magie.\n\nKo'ragh muss getötet werden, bevor die Oger einen Weg finden, seine einzigartigen Kräfte zu replizieren. Begebt Euch nach Hochfels und bezwingt Ko'ragh!", sourceObjective = "Bezwingt Ko'ragh in Hochfels.", completion = "Ko'ragh is' besiegt. Ihr seid wirklich so mächtig, wie's immer heißt, Kommandant. Es macht mich stolz, an Eurer Seite zu kämpf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[37758] = { id = 37758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kaiserstieg: Kaiser Mar'gok", description = "Die Lage ist günstig für einen entscheidenden Schlag gegen Hochfels, Kommandant. Wir müssen handeln.\n\nKaiser Mar'gok ist Nachkomme einer langen Linie von Zauberern und herrscht unangefochten über Hochfels. Er ist ebenso durchtrieben wie rücksichtslos und hat einem Bündnis mit der Eisernen Horde nur zugestimmt, weil er erkannt hat, wie gefährlich es wäre, sich gegen sie zu stellen.\n\nReist nach Hochfels und besiegt Kaiser Mar'gok. Ohne seinen Regenten wird das Ogerimperium über viele Jahre hinaus im Chaos versinken.", sourceObjective = "Bezwingt Kaiser Mar'gok in Hochfels.", completion = "Ein glänzender Sieg, Kommandant! Kaiser Mar'gok is' besiegt. Ihr seid 'n echter Champion der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[37762] = { id = 37762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzraffinerie: Herz des Berges", description = "Die Schwarzfelsorcs kämpfen wie kein anderer Klan. Ihre Waffen und Rüstungen werden in ihren widernatürlichen Schmelztiegeln gefertigt.\n\nIn den Tiefen der Schwarzfelsgießerei befindet sich ein Schmelzofen, der von einer urzeitlichen Macht angetrieben wird, das Herz des Berges. Zerstört es und wir unterbrechen damit ihren Waffennachschub.\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt das Herz des Berges.", sourceObjective = "Bezwingt das Herz des Berges am Schmelzofen in der Schwarzfelsgießerei.", completion = "Sehr gut, Kommandant. Jetzt wo Ihr das Herz des Berges ausm Weg geräumt habt, kann der Schwarzfelsklan seinen mächtigst'n Schmelzofen nich' mehr benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37763] = { id = 37763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarze Schmiede: Kromog", description = "Kommandant. Späher der Frostwölfe berichten, dass die Minenarbeiter des Schwarzfelsklans auf einen Magnaron gestoßen sind, den sie zwingen, ihnen bei der Herstellung ihrer Höllenmaschinen zu helfen. Sie nennen ihn \"Kromog\".\n\nWir müssen ihn vernichten, {name}. Begebt Euch zur Schwarzfelsgießerei und besiegt Kromog.", sourceObjective = "Bezwingt Kromog in der Schwarzfelsgießerei.", completion = "Ausgezeichnet, Kommandant! So entschlossenes Handeln habe ich das letzte Mal erlebt, als Garrosh Höllschrei unsere Truppen in Nordend anführte.", sourceObjectiveStatus = "unverified-source-field" }
quests[37764] = { id = 37764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiserne Fertigung: Admiralin Gar'an", description = "Unsere Truppen gewinnen an Boden auf dem Festland, aber auf See warten wir immer noch auf einen Sieg. Wir müssen die Anführer der Eisernen Horde ausschalten, solange sie sich im Hafen befinden.\n\nDie Flotte der Eisernen Horde wird von Admiralin Gar'an befehligt, die erste der sogenannten Eisernen Jungfern. Dank ihres brillanten taktischen Geschicks konnten sie und ihre beiden Leutnants Marak und Sorka bisher alle Gegner vernichten, die sich ihnen entgegengestellt haben.\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt Admiralin Gar'an.", sourceObjective = "Bezwingt Admiralin Gar'an in der Schwarzfelsgießerei.", completion = "Gute Arbeit, Kommandant. Mit Admiralin Gar'an verliert die Flotte der Eiserne Horde 'ne fähige Befehlshaberin. Das is'n schwerer Verlust für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[37765] = { id = 37765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfausts Schmelztiegel: Schwarzfaust", description = "Grommash Höllschrei verdankt seine Macht über die Eiserne Horde auch der Stärke seiner Kriegsherren. Die Zeit ist reif für einen entscheidenden Schlag.\n\nSchwarzfaust, Kriegsherr des Schwarzfelsklans, ist ein erbitterter Krieger und ein skrupelloser Tyrann. Innerhalb der Eisernen Horde steht nur Grommash über ihm. Er überwacht den Betrieb der Gießerei von seinem Sitz oberhalb des Schmelztiegels.\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt Schwarzfaust.", sourceObjective = "Bezwingt Schwarzfaust in der Schwarzfelsgießerei.", completion = "Einer der brutalsten Orcs, die jemals diese oder unsere Welt unsicher gemacht ham, wurde besiegt. Ich gratulier' Euch zu diesem Sieg und ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37766] = { id = 37766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ummauerte Stadt: Farnspore", description = "Kaum hat man eine Gefahr abgewendet, wartet schon die nächste. Diese vom Licht verlassene Welt würde uns mit Haut und Haaren verschlingen, selbst wenn es hier keine Horde zu bekämpfen gäbe.\n\nFarnspore, der urzeitliche Tiefenwanderer, wurde durch die Anwesenheit der Eisernen Horde aus den Gewässern um Hochfels angelockt. Das Ding verbreitet sich wie eine Krankheit, {name}. Macht dem ein Ende!\n\nReist nach Hochfels und besiegt Farnsporn, bevor er zu mächtig wird.", sourceObjective = "Bezwingt Farnspore in Hochfels.", completion = "Ausgezeichnet! So wird sich Farnspores Pilzbefall nicht über ganz Draenor ausbreiten. Habt vielen Dank, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37767] = { id = 37767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Sanktum: Ko'ragh", description = "Sagt Euch der Name \"Ko'ragh\" etwas? Er gehört zu den Ogern von Hochfels. Vor einiger Zeit haben sie ein Relikt ausgebuddelt und das Ding hat jeden getötet, der damit in Kontakt gekommen ist. Mit Ausnahme von Ko'ragh... Er ist seitdem fast völlig immun gegen jede Art von Magie.\n\nSolche Kräfte sind nix für Oger! Begebt Euch nach Hochfels und besiegt Ko'ragh, bevor die Oger irgendwie rausfinden, wie sie ihn gegen uns verwenden können.", sourceObjective = "Bezwingt Ko'ragh in Hochfels.", completion = "Hervorragend! Ihr habt Ko'ragh besiegt. Ihr seid wirklich so mächtig, wie immer behauptet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[37768] = { id = 37768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kaiserstieg: Kaiser Mar'gok", description = "Ich hab diese Oger nie ernst genommen, bis ich mal eine Hochfelslegion gesehen habe. Wie ein Wall aus Muskeln und Stahl und dahinter die besten Zauberer des Kaisers. Unterschätzt diese Oger nicht!\n\nKaiser Mar'gok ist der oberste Herrscher von Hochfels. Der ist natürlich clever und hat sich rechtzeitig mit der Eisernen Horde verbündet. Wenn wir dieses Party sprengen wollen, fangen wir am besten ganz oben an.\n\nReist nach Hochfels und besiegt Kaiser Mar'gok!", sourceObjective = "Bezwingt Kaiser Mar'gok in Hochfels.", completion = "Gute Arbeit! Heute haben wir ihnen einen schweren Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37769] = { id = 37769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzraffinerie: Herz des Berges", description = "Die Waffen, die die Krieger des Schwarzfelsklans verwenden , wurden in verfluchten Flammen aus dem Atem einer Kreatur aus reinem Feuer geschmiedet: das Herz des Berges. Wir müssen ihren Nachschub unterbrechen, <Junge/Mädchen>! Wenn Ihr diese höllische Kreatur besiegt, werden die Schwarzfelsorcs nicht genug Energie haben, um ihren Schmelzofen zu betreiben.\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt das Herz des Berges.", sourceObjective = "Bezwingt das Herz des Berges am Schmelzofen in der Schwarzfelsgießerei.", completion = "Ausgezeichnet, Kommandant! Jetzt, da das Herz des Berges im Staub liegt, können die Schwarzfelsorcs bald nur noch Knüppel schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37770] = { id = 37770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarze Schmiede: Kromog", description = "Eure Späher berichten, dass die Minenarbeiter des Schwarzfelsklans auf einen Magnaron gestoßen sind, der ihnen hilft, ihre Höllenmaschinen zu bauen. Sie nennen ihn \"Kromog\".\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt dieses Ungetüm!", sourceObjective = "Bezwingt Kromog in der Schwarzfelsgießerei.", completion = "Jetzt da Kromog besiegt wurde, wird die Eiserne Horde nicht mehr so viele ihrer Höllenmaschinen an die Front bringen können. Ihr habt heute viele Leben gerettet, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37771] = { id = 37771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiserne Fertigung: Admiralin Gar'an", description = "\"Wer eine Wand niederreißen will, sollte zunächst mit dem Fundament beginnen.\" Eine alte Zwergenweisheit. Wenn wir ihre Befehlshaber ausschalten, gerät die gesamte Eiserne Horde ins Wanken.\n\nAdmiralin Gar'an ist die Befehlshaberin der Flotte der Eisernen Horde und der Kopf der sogenannten \"Eisernen Jungfern\". Mit ihren Leutnants Marak und Sorka beherrscht sie die Meere von Draenor.\n\nIhr werdet dafür sorgen, dass es damit ein Ende hat, {name}. Reist zur Schwarzfelsgießerei und besiegt Admiralin Gar'an.", sourceObjective = "Bezwingt Admiralin Gar'an in der Schwarzfelsgießerei.", completion = "Großartige Arbeit, Kommandant! Wenn das so weiter geht, entreißen wir der Eisernen Horde schon noch die Kontrolle über die See!", sourceObjectiveStatus = "unverified-source-field" }
quests[37772] = { id = 37772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfausts Schmelztiegel: Schwarzfaust", description = "Unser alter Freund Grommash kann nicht ohne seine Kriegsherren über die Eiserne Horde herrschen. Sie sind es, die die Klans bei der Stange halten. Es wird Zeit, ihnen einen Schlag zu versetzen, von dem sie sich nicht so einfach erholen werden! Schwarzfaust, der Kriegsherr des Schwarzfelsklans, ist ein erbitterter Krieger und ein skrupelloser Tyrann. Innerhalb der Eisernen Horde steht nur Grommash über ihm. Er überwacht den Betrieb der Gießerei von seinem Sitz im Schmelztiegel.\n\nBegebt Euch zur Schwarzfelsgießerei und besiegt Schwarzfaust.", sourceObjective = "Bezwingt Schwarzfaust in der Schwarzfelsgießerei.", completion = "Ihr habt es geschafft! In der Gießerei herrscht heilloses Durcheinander. Wir haben unserem Gegner heute einen gewaltigen Schlag verpasst. Ausgezeichnete Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37773] = { id = 37773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amethon muss sterben!", description = "Vorarbeiter Eksos von unserem Außenposten in Talador hat herausgefunden, warum wir in letzter Zeit verstärkt seismische Aktivitäten hatten.\n\nEr erzählte etwas von einem Riesen, äh... einem Erdzorn, so heißen diese Dinger glaub ich, der in einer Höhle oberhalb von Kuuros Bergwerk lebt. Der Zorn ist mit mächtigen Kristallen bedeckt, die ihn durch ihr lautes Summen zur Raserei bringen!\n\nLeider haben wir niemanden mit genug Feuerkraft, der so ein Monstrum erledigen und uns Proben von diesen Kristallen bringen könnte. Könntet Ihr uns vielleicht helfen, Kommandant?", sourceObjective = "Beschafft einen vibrierenden Draenitkristall von Amethon über Kuuros Bergwerk in Talador.", progress = "Was habt Ihr da, Kommandant?", completion = "Sehr gut, das muss einer von diesen Kristallen sein, von denen Eksos die ganze Zeit redet. Wir haben unsere besten Leute darauf angesetzt, die ihn sofort untersuchen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37774] = { id = 37774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'thul muss sterben!", description = "Eine Armee aus Saberongeistern. Da braucht Ihr gar nicht so lachen, Kommandant. Wenn wir jetzt die Däumchen drehen, müssen wir uns auf so etwas gefasst machen!\n\nGor'thul, ein Schamane der Zerschmetterten Hand, wurde an den Spitzen von Arak im Blutmähnenrevier gesichtet. Ungefähr zur gleichen Zeit haben wir erste Berichte erhalten, dass Saberongeister unsere Versorgungskarawanen angreifen.\n\nWir sollten kein Risiko eingehen, Kommandant. Ich denke, Ihr solltet persönlich dorthin reisen und dem Spuk ein Ende bereiten.", sourceObjective = "Tötet Gor'thul im Blutmähnenrevier an den Spitzen von Arak.", completion = "Ausgezeichnet, Kommandant. Es ist beruhigend zu wissen, dass wir uns nicht auch noch um Saberongeister Sorgen machen müssen, die uns ans Leder wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37775] = { id = 37775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifizierer Darkoor muss sterben!", description = "Habt Ihr jemals vom Ring des Blutes gehört, Kommandant?\n\nEs ist ziemlich einfach. Dieser riesige Oger namens Mogor schaut anderen gerne dabei zu, wie sie mit wilden Bestien um ihr Leben kämpfen. Ein ehrgeiziger Goblin namens Gurgthock arrangiert die Kämpfe und streicht den Profit ein.\n\nWie dem auch sei, Gurgthock und ich sind gute Kumpels und er hat einen speziellen Schaukampf auf die Beine gestellt, nur für Euch! Toll, was? Flüstert ihm einfach ins Ohr: \"Ich suche den Suchenden.\"", sourceObjective = "Sprecht mit Gurgthock am Ring des Blutes in Nagrand und gewinnt den Schaukampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[37776] = { id = 37776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefensog muss sterben!", description = "Grüße, Kommandant!\n\nIch habe schlechte Nachrichten.\n\nWir haben einige der Fischer aus dieser Gegend als Spione angeheuert – wir zahlen ihnen ein paar Münzen, damit sie mit ihren Booten nördlich des Umbrafenns rausfahren und herausfinden, was die Eiserne Horde vor hat. Ein gutes Geschäft für beide Seiten, würde man meinen, nicht wahr?\n\nLeider ganz und gar nicht, denn von den Booten, die rausgefahren sind, ist bisher keins zurückgekehrt. Anscheinend steckt ein riesiger Wasserelementar namens Tiefensog dahinter. Er macht kurzen Prozess mit allen, die in diese Richtung fahren.\n\nKönntet Ihr Euch vielleicht um dieses Problem kümmern, Kommandant?", sourceObjective = "Tötet Tiefensog im Tanaankanal nördlich des Umbrafenns im Schattenmondtal.", completion = "Vielen Dank, Kommandant! Wir hoffen, die Berichte, die wir vom Tanaankanal erhalten, werden sich in den nächsten Monaten als hilfreich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37777] = { id = 37777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beben muss sterben!", description = "Euer Außenposten in Gorgrond hat ein ernsthaftes Saberonproblem, Kommandant, und wir können es uns nicht leisten, mehr Truppen dorthin zu schicken. Aber ich hab eine Idee.\n\nAn der Westküste von Gorgrond lebt ein riesiger Wurm namens Beben, auch bekannt als der Verschlinger von Hummerstroks. Wenn Ihr dieses gefräßige Ding erlegt und, nun ja, einen Haufen halb verdautes Hummerstrokfleisch mitbringt, können wir das Zeug hier kochen und dann dorthin transportieren. Das würde die Saberon für ein Weilchen fern halten!", sourceObjective = "Tötet Beben westlich von Gorgoreks Sturz in Gorgrond und beschafft einen Haufen halb verdautes Hummerstrokfleisch.", progress = "Eure Befehle, Kommandant?\n\nUnd was riecht hier denn so komisch?!", completion = "Sehr gut. Mit diesem Fleisch halten wir uns diese nervtötenden Saberon eine Weile vom Leib.", sourceObjectiveStatus = "unverified-source-field" }
quests[37778] = { id = 37778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmlord Ik'rix muss sterben!", description = "Wir haben eine ganz neue Methode entwickelt, unsere Waffen und Rüstungen zu härten. Wir verwenden dabei den Panzer von Eisverheerern. Diese bahnbrechende Idee wird uns einen echten Vorteil verschaffen, Kommandant!\n\nDas Problem ist nur, dass die Verheerer sich nicht freiwillig von ihren Panzern trennen. Es gibt da ein besonders großes Exemplar an den Südwindklippen am Frostfeuergrat namens Schwarmlord Ik'rix – wenn Ihr diesen Verheerer erlegt, hätten wir genug Panzer für mehrere Wochen!", sourceObjective = "Besorgt den Eisbrecherpanzer von Schwarmlord Ik'rix an den Südwindklippen am Frostfeuergrat.", progress = "Ja, Kommandant?", completion = "Vielen Dank, Kommandant. Wir werden uns gleich an die Arbeit machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37779] = { id = 37779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gegen Schuppen" }
quests[37780] = { id = 37780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun", description = "Gul'dans zuverlässigster Agent Teron'gor ist in Auchindoun in Talador eingedrungen und hat damit begonnen, die zahllosen Seelen darin zu verschlingen. Wir dürfen nicht zulassen, dass dieser ruchlose Hexenmeister dadurch noch stärker wird.\n\nBetretet das heilige Mausoleum von Auchindoun und vertreibt Teron'gor und den Rest des Schattenrats bevor noch mehr Schaden entsteht.", sourceObjective = "Bezwingt Teron'gor in Auchindoun.", completion = "Ihr habt 'nen weit'ren Agenten von Gul'dan besiegt, Kommandant. Unser heutiger Sieg ist 'n schwerer Schlag für ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[37781] = { id = 37781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutschlägermine", description = "Die Oger der Blutschläger sind rücksichtslose Sklaventreiber, Kommandant. Unschuldige aus ganz Draenor werden in die Tiefen der vulkanischen Blutschlägermine im Frostfeuergrat verschleppt. Dort müssen sie unter schrecklichen Arbeitsbedingungen gewaltige Mengen Edelsteine und Erz fördern. Keiner dieser Gefangenen ist jemals zurückgekehrt.\n\nWir vermuten, dass die Oger mittlerweile nach etwas anderem suchen: ein uraltes Relikt, das ihrem Zaubererkönig unvorstellbare Macht verleihen würde.\n\nDer Oger Gug'rokk herrscht mit eiserner Faust über die Blutschlägermine. Wenn Ihr ihn erledigt, setzt Ihr die Mine ebenfalls außer Betrieb.", sourceObjective = "Bezwingt Gug'rokk in der Blutschlägermine.", completion = "Die Oger der Blutschläger sin' erledigt – genauso wie die Pläne von Kaiser Mar'gok, sich das Relikt in der Mine unter den Nagel zu reißen.\n\nDas ist wirklich mal 'ne gute Nachricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37782] = { id = 37782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmgleisdepot", description = "Wir müssen schnell handeln, Kommandant. Der Grimmzug fährt in Kürze ab, um ein ganzes Bataillon an Truppen nach Shattrath zu transportieren. Gerüchten zufolge ist der Zug mit einer mächtigen Waffe ausgestattet, die den schützenden Schild der inneren Stadt zerstören kann. \n\nDen Begleitschutz auf dem Weg nach Talador übernimmt Himmelsfürstin Tovra. Wir haben nur eine Chance: Haltet Tovra und den Grimmzug auf, bevor sie Shattrath erreichen!", sourceObjective = "Bezwingt Himmelsfürstin Tovra im Grimmgleisdepot.", completion = "Der Angriff auf den Grimmzug, das war 'n Schlag, der gesessen hat! Dank Euch wird die Eiserne Horde erstmal 'n Weilchen brauchen, um Truppen zusammenzuziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37783] = { id = 37783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisendocks", description = "Die Eisendocks sind für die Eiserne Horde von strategischer Bedeutung. Unsere Späher berichten von erhöhter Aktivität an den Docks, was darauf schließen lässt, dass ein Angriff kurz bevorsteht.\n\nIhren Angaben zufolge hat Skulloc, Sohn von Gruul, die Schwarzfelsgießerei verlassen, bis an die Zähne bewaffnet mit mächtigen Kanonen. Er wurde auf eines ihrer gewaltigsten Kriegsschiffe verladen. Ganz egal, wo sie planen, zuzuschlagen, Ihr müsst einen Ausfall auf die Eisendocks durchführen und Skulloc vernichten, noch bevor das Schiff ablegt.", sourceObjective = "Bezwingt Skulloc in den Eisendocks.", completion = "Ohne Skulloc und ihre wertvollen Docks ähnelt die Eiserne Horde 'nem Wolfsrudel, das in seiner eigenen Höhle gefangen is'... ohne die Möglichkeit, selbst auf Jagd zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37784] = { id = 37784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondgrabstätte", description = "Ner'zhul war einst einer der angesehensten Orcs auf Draenor. Er war ein mächtiger Schamane und herrschte als weiser Häuptling über den Schattenmondklan. Doch jetzt biedert er sich bei der Eisernen Horde an und kehrt damit allem den Rücken, für das er vorher gestanden hat. Rücksichtslos opfert er die Geister seiner Vorfahren, um dunkle, verbotene Mächte zu nutzen und das nur, um Höllschrei zu gefallen.\n\nDer Schattenmondklan ist verloren, Kommandant. Betretet die uralte Begräbnisstätte und bereitet Ner'zhuls Wahnsinn ein Ende, bevor er ganz Draenor in die alles verschlingende Leere hinabzieht.", sourceObjective = "Bezwingt Ner'zhul in der Schattenmondgrabstätte.", completion = "Ich kann fühl'n, wie die Geister der Vorfahren von Draenor nach Eurem Sieg über Ner'zhul aufatmen. Ihr habt eine von Grommashs mächtigsten Waffen vernichtet, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37785] = { id = 37785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsnadel", description = "Die oberste Weise Viryx hat eine von Kristallen betriebene Superwaffe am höchsten Punkt der Himmelsnadel an den Spitzen von Arak fertiggestellt. Ihr Ziel ist es, alle 'niederen Völker' im Namen ihres Gottes Rukhmar zu vernichten.\n\nDie Ausgestoßenen der Arakkoa wurden von dieser Waffe in wenigen Sekunden fast komplett ausgelöscht. Ihr müsst Viryx aufhalten, bevor sie ihre Waffe auf unsere Garnison richtet, Kommandant.", sourceObjective = "Bezwingt die Oberste Weise Viryx auf der Himmelsnadel.", completion = "Vielleicht ham die Jünger von Rukhmar jetzt mehr Respekt vor uns 'niederen Völkern'.", sourceObjectiveStatus = "unverified-source-field" }
quests[37786] = { id = 37786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Immergrüne Flor", description = "Die Kirin Tor haben einen Außenposten in Gorgrond errichtet, der über ein Portal mit Sturmwind verbunden ist, um schnell Verstärkung für den Angriff auf die Schwarzfelsgießerei heranzuschaffen. In ihrer unermesslichen Weisheit haben sie diesen Außenposten aber ausgerechnet im Immergrünen Flor gebaut, also mitten in der Heimat der Botani und des mächtigsten aller Genesaurier: Yalnu.\n\nDer Außenposten wurde schnell überrannt und es ist nur eine Frage der Zeit, bis sich die Überwucherung bis nach Sturmwind ausbreitet... und von dort aus über ganz Azeroth.", sourceObjective = "Bezwingt Yalnu im Immergrünen Flor.", completion = "Diese Zauberer ham nich' gerade vorausschauend geplant. Ihr Tod is' Strafe genug dafür. Wir sollten dankbar sein, dass wir's geschafft ham, die Überwucherung zu stoppen, bevor sie unsere Welt erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37787] = { id = 37787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obere Schwarzfelsspitze", description = "Höllschreis Vorhut des Eisernen Marsches hat den Schwarzfels erreicht und sich mit Kriegsfürstin Zaela vom Drachenmalklan verbündet. Von dort aus bereitet sich die Eiserne Horde nun darauf vor, in Azeroth einzufallen. Gleichzeitig arbeitet Zaela an einer Weltuntergangswaffe im Herzen des Berges, mit der jeder nennenswerte Widerstand im voraus vernichtet werden soll.\n\nIhr müsst Zaela ein für alle Mal Einhalt gebieten, Kommandant. Sie ist uns schon lange ein Dorn im Auge.", sourceObjective = "Bezwingt Kriegsfürstin Zaela an der Oberen Schwarzfelsspitze.", completion = "Jetzt, wo Kriegsfürstin Zaela aus dem Weg is', können wir uns ganz auf Draenor und die Hauptstreitmacht der Eisernen Horde konzentrier'n. Jetzt is' Schluss mit dem Versteckspiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[37788] = { id = 37788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Gutreks Spalter", description = "Die Oger in Nagrand erzählen von einer uralten Waffe, die sie Gutreks Spalter nennen. Ich würde dieses Relikt gerne näher untersuchen.\n\nEin Schatzjäger der Goblins namens Val Goldschaufel hat herausgefunden, wo die Waffe liegt. Leider ist er irgendwo in der Zerschlagenen Anhöhe verschwunden – möglicherweise nach einer Begegnung mit den dort ansässigen Kreaturen.", sourceObjective = "Durchsucht die Oger innerhalb der Zerschlagenen Anhöhe nach Hinweisen zu Goldschaufels Entdeckung.", sourceObjectiveStatus = "unverified-source-field" }
quests[37789] = { id = 37789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obere Schwarzfelsspitze", description = "Höllschreis Vorhut des Eisernen Marsches hat den Schwarzfels erreicht und sich mit Kriegsfürstin Zaela vom Drachenmalklan verbündet. Vom Schwarzfels aus will die Eiserne Horde bald Azeroth überfallen. Gleichzeitig bastelt Zaela an einer Weltuntergangswaffe im Herzen des Berges, mit der sie alles platt machen will, was sich ihnen in den Weg stellt.\n\nIhr müsst Zaela ein für alle Mal ausschalten, Kommandant. Sie ist uns schon lange ein Dorn im Auge.", sourceObjective = "Bezwingt Kriegsfürstin Zaela an der Oberen Schwarzfelsspitze.", completion = "Jetzt, wo Kriegsfürstin Zaela aus dem Weg ist, können wir uns ganz auf Draenor und unsere Freunde von der Eisernen Horde konzentrieren. Jetzt ist Schluss mit dem Versteckspiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[37790] = { id = 37790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Immergrüne Flor", description = "Die Kirin Tor haben einen Außenposten in Gorgrond, der über ein Portal mit Sturmwind verbunden ist. Die Idee war, schnell Verstärkung für den Angriff auf die Schwarzfelsgießerei heranbringen zu können. Leider haben sie diesen Außenposten aber ausgerechnet im Immergrünen Flor gebaut, wo es nur so von Botani wimmelt. Und als wär' das nicht genug, gibt es dort noch diesen riesigen Genesaurier Yalnu.\n\nDer Außenposten wurde natürlich ruckzuck überrannt und jetzt ist nur eine Frage der Zeit, bis sich die Überwucherung bis nach Sturmwind ausbreitet... und von dort aus über ganz Azeroth.", sourceObjective = "Bezwingt Yalnu im Immergrünen Flor.", sourceObjectiveStatus = "unverified-source-field" }
quests[37791] = { id = 37791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsnadel", description = "Die oberste Weise Viryx hat eine von Kristallen betriebene Superwaffe am höchsten Punkt der Himmelsnadel an den Spitzen von Arak fertiggestellt. Sie will alle 'niederen Völker' im Namen ihres Gottes Rukhmar vernichten.\n\nDie Ausgestoßenen der Arakkoa hat sie mit dieser Waffe in wenigen Sekunden fast komplett ausgelöscht. Ihr müsst Viryx aufhalten, bevor sie ihre Waffe auf unsere Garnison richtet, Kommandant.", sourceObjective = "Bezwingt die Oberste Weise Viryx auf der Himmelsnadel.", progress = "Die oberste Weise Viryx ist eine Gefahr für alles, was Ihr erreicht habt. Sie muss um jeden Preis aufgehalten werden.", completion = "Vielleicht haben die Jünger von Rukhmar jetzt mehr Respekt vor uns 'niederen Völkern'.", sourceObjectiveStatus = "unverified-source-field" }
quests[37792] = { id = 37792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondgrabstätte", description = "Ner'zhul war nicht immer böse – einst war er ein mächtiger Schamane und herrschte als weiser Häuptling über den Schattenmondklan. Doch jetzt biedert er sich bei der Eisernen Horde an und kehrt damit allem den Rücken, für das er vorher gestanden hat. Rücksichtslos opfert er die Geister seiner Vorfahren, um dunkle, verbotene Mächte zu nutzen und das nur, um Höllschrei zu gefallen.\n\nBetretet die uralte Begräbnisstätte und bereitet Ner'zhuls Wahnsinn ein Ende, bevor er ganz Draenor in die Leere mitreißt.", sourceObjective = "Bezwingt Ner'zhul in der Schattenmondgrabstätte.", completion = "Ich bin kein Schamane, ganz sicher nicht, aber selbst ich fühle, wie die Geister der Vorfahren nach Eurem Sieg über Ner'zhul aufatmen. Ihr habt eine ziemlich mächtige Waffe von Grommash zerstört, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37793] = { id = 37793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisendocks", description = "Die Eisendocks sind für die Eiserne Horde von strategischer Bedeutung. Unsere Späher berichten von erhöhter Aktivität an den Docks, anscheinend steht ein Angriff kurz bevor.\n\nWir wissen auch, dass Skulloc, Sohn von Gruul, die Schwarzfelsgießerei verlassen hat, bis an die Zähne bewaffnet mit mächtigen Kanonen. Er wurde auf eines ihrer gewaltigsten Kriegsschiffe verladen. Ganz egal, wo sie planen, zuzuschlagen – Ihr müsst einen Ausfall auf die Eisendocks durchführen und Skulloc vernichten, noch bevor das Schiff ablegt.", sourceObjective = "Bezwingt Skulloc in den Eisendocks.", completion = "Ohne Skulloc und ihre wertvollen Docks wird die Eiserne Horde eine Weile keine weiteren Angriffe mehr starten können!", sourceObjectiveStatus = "unverified-source-field" }
quests[37794] = { id = 37794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmgleisdepot", description = "Wir müssen schnell handeln, Kommandant. Der Grimmzug fährt in Kürze ab, um ein ganzes Bataillon an Truppen nach Shattrath zu transportieren. Gerüchten zufolge ist der Zug mit einer mächtigen Waffe ausgestattet, die den schützenden Schild der inneren Stadt zerstören kann. \n\nDen Begleitschutz auf dem Weg nach Talador übernimmt Himmelsfürstin Tovra. Wir haben nur eine Chance: Haltet Tovra und den Grimmzug auf, bevor sie Shattrath erreichen!", sourceObjective = "Bezwingt Himmelsfürstin Tovra im Grimmgleisdepot.", sourceObjectiveStatus = "unverified-source-field" }
quests[37795] = { id = 37795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutschlägermine", description = "Die Oger der Blutschläger sind rücksichtslose Sklaventreiber, Kommandant. Unschuldige aus ganz Draenor werden in die Tiefen der vulkanischen Blutschlägermine im Frostfeuergrat verschleppt. Dort müssen sie bis zum Umfallen schuften, um gewaltige Mengen Edelsteine und Erz fördern. Keiner dieser Gefangenen ist jemals zurückgekehrt.\n\nWir vermuten, dass die Oger mittlerweile nach etwas anderem suchen: ein uraltes Relikt, das ihrem Zaubererkönig unvorstellbare Macht verleihen würde.\n\nDer Oger Gug'rokk herrscht mit eiserner Faust über die Blutschlägermine. Wenn Ihr ihn erledigt, setzt Ihr die Mine ebenfalls außer Betrieb.", sourceObjective = "Bezwingt Gug'rokk in der Blutschlägermine.", completion = "Die Oger der Blutschläger sind erledigt und mit ihnen Kaiser Mar'goks Pläne, das Relikt in der Mine in seinen Besitz zu bringen.\n\nDas ist eineder besten Nachrichten, die ich seit langem gehört habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37796] = { id = 37796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun", description = "Kommandant, Gul'dans zuverlässigster Agent Teron'gor ist in Auchindoun in Talador eingedrungen und hat damit begonnen, die zahllosen Seelen darin zu verschlingen. Wir dürfen nicht zulassen, dass dieser ruchlose Hexenmeister dadurch noch stärker wird.\n\nBetretet das heilige Mausoleum von Auchindoun und vertreibt Teron'gor und den Rest des Schattenrats bevor noch mehr Schaden entsteht.", sourceObjective = "Bezwingt Teron'gor in Auchindoun.", completion = "Gute Arbeit, Kommandant! Dieser Schlag gegen Gul'dan hat gesessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37797] = { id = 37797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutreks Spalter: Das erste Teil", description = "Im Notizbuch finden sich Hinweise darauf, wo sich die einzelnen Teile von Gutreks Spalter befinden. Ein Eintrag enthält erste Anhaltspunkte:\n\n\"Der Knauf wurde zur Zerschlagenen Anhöhe gebracht. Er sollte in den Schädel des ersten Gegners eingesetzt werden, den Gutrek im Kampf tötete. Anscheinend handelte es sich dabei um eine riesige Kreatur, gegen die er in der Skelettgrube antrat.\"", sourceObjective = "Folgt dem Hinweis aus dem Notizbuch, um Gutreks Schwertknauf zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37798] = { id = 37798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutreks Spalter: Das zweite Teil", description = "Ihr sucht weiter nach Gutreks Spalter. Im Notizbuch findet sich folgender Eintrag:\n\n\"Das Schwertheft sollte in den Marschen vergraben werden, inmitten der Schlangen, durch deren Gift Gutrek starb. Es finden sich Hinweise auf einen Spiralstein, mit dem es bedeckt wurde, um Gutreks Geist fernzuhalten.\"", sourceObjective = "Folgt dem Hinweis aus dem Notizbuch, um das Heft von Gutreks Spalter zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37799] = { id = 37799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutreks Spalter: Das letzte Teil", description = "Jetzt fehlt nur noch das letzte Teil. Im Notizbuch findet sich dazu Folgendes:\n\n\"Das letzte Teil, Gutreks Klinge, sollte an einem Ehrenplatz gut sichtbar oberhalb des Ring des Blutes ausgestellt werden. Ich habe es dort noch nicht selbst gesehen, aber es soll sich irgendwo befinden, wo man eine gute Aussicht auf alle Kämpfe hat.\"", sourceObjective = "Folgt dem Hinweis aus dem Notizbuch, um Gutreks Klinge zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37800] = { id = 37800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Start the Garrison Campaign" }
quests[37802] = { id = 37802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Hilt Looted" }
quests[37803] = { id = 37803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Pommel Looted" }
quests[37804] = { id = 37804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Blade Looted" }
quests[37805] = { id = 37805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Looted" }
quests[37811] = { id = 37811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutreks Spalter: Die Geisterschmiede", description = "Jetzt, da alle Teile gefunden wurden, bleibt nur noch eins zu tun: Gutreks Spalter neu zu schmieden. In Goldschaufels Notizbuch wird erwähnt, dass dies nur an dem Ort möglich ist, an dem die Waffe ursprünglich zerlegt wurde.\n\nLaut Notizbuch ist dies in einer \"Geisterschmiede\" geschehen, die sich irgendwo in der Nähe der Schlucht befinden soll. Findet die Schmiede und fügt darauf die Teile zusammen, die Ihr gesammelt habt.", sourceObjective = "Findet die Geisterschmiede in der Donnergrundschlucht und schmiedet Gutreks Spalter neu.", progress = "Habt Ihr die alte Klinge gefunden, die Dr. Jones gesucht hat?", completion = "Diese Waffe stimmt genau mit der Beschreibung von Dr. Jones überein. Ich werde dafür sorgen, dass er sie erhält. \n\nHier ist Eure Belohnung, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37813] = { id = 37813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amethon muss sterben!", description = "Vorarbeiter Grobash von unser'm Außenposten in Talador hat rausgefunden, warum wir in letzter Zeit so viel seismische Aktivitäten hatt'n.\n\nEr hat was von 'nem Erdzorn namens Amethon erzählt, der in 'ner Höhle über Kuuros Bergwerk lebt. Der Zorn is' mit mächtigen Kristallen bedeckt, die ihn durch ihr lautes Summen ganz meschugge machen!\n\nWir brauchen 'ne Probe davon, um herauszufind'n, warum die Kristalle so mächtig sind. Ich würde mich nich' an Euch wenden, wenn ich jemand ander'n schicken könnte, Kommandant.", sourceObjective = "Beschafft einen vibrierenden Draenitkristall von Amethon über Kuuros Bergwerk in Talador.", progress = "Was is' das für 'n Mordslärm? Is' das ein Kristall von Amethon in Eurer Hand?", completion = "Ihr habt mal wieder den Tag gerettet, Kommandant. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37814] = { id = 37814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'thul muss sterben!", description = "Wir bekomm'n Berichte über richtig finsteren Voodoo an den Spitzen von Arak, Kommandant.\n\nGor'thul, ein Schamane der Zerschmetterten Hand, treibt sich in der Gegend rum und seitdem hör'n wir immer wieder von Saberongeistern, die uns're Versorgungskarawanen und unsre Verbündeten unter den Arakkoa überfall'n.\n\nIch denk', wir sollten kein Risiko eingeh'n. Ihr kümmert Euch am besten persönlich um diesen Schamanen, bevor die Sache ausm Ruder läuft.", sourceObjective = "Tötet Gor'thul im Blutmähnenrevier an den Spitzen von Arak.", progress = "Grüße, Kommandant. Habt Ihr Gor'thul erwischt?", completion = "Die Geister sin' Euch wohlgesonnen, Kommandant. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37815] = { id = 37815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifizierer Darkoor muss sterben!", description = "Der Goblin Gurgthock erwartet Euch am Ring des Blutes in Nagrand, <Scheff/Scheffin>.\n\nAnscheinend veranstaltet Mogor, der Herr des Rings, dort 'nen Schaukampf und er möchte, dass Ihr gegen seine neueste Anschaffung antretet.\n\nIch denk', das ist 'ne sichere Sache, Kommandant. Ich hab schon viel von diesem Goblin gehört. Wenn Ihr so weit seid, flüstert ihm einfach zu \"Ich suche den Suchenden.\"", sourceObjective = "Sprecht mit Gurgthock am Ring des Blutes in Nagrand und gewinnt den Schaukampf.", completion = "Die Nachricht von Euren Taten verbreiten sich bereits wie 'n Lauffeuer. Wenn die Oger vorher keine Angst vor Eurer Macht hatt'n, ham sie die jetzt auf jeden Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[37816] = { id = 37816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefensog muss sterben!", description = "Wir ham 'n Problem, Kommandant.\n\nWir ham 'n paar kleinere Boote in den Tanaankanal nördlich des Umbrafenns geschickt, um die Allianzbasis im Schattenmondtal und die Eiserne Horde im Tanaandschungel auszukundschaften.\n\nDas Problem is', dass alle Boote, die wir rübergeschickt ham, in Einzelteilen zurückgekomm'n sind – wenn wir überhaupt wieder was von ihnen gehört ham. Wir glauben, dass ein Wasserelementar namens Tiefensog dahintersteckt.\n\nIch weiß, dass Ihr ziemlich viel zu tun habt, aber wenn Ihr diese Kreatur aus dem Weg räumt, würde uns das gewaltig helfen.", sourceObjective = "Tötet Tiefensog im Tanaankanal nördlich des Umbrafenns im Schattenmondtal.", completion = "Vielen Dank für Eure Hilfe, Kommandant. Dieses Spionier'n wird sich in den nächst'n Monaten noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37817] = { id = 37817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beben muss sterben!", description = "Der Außenposten in Gorgrond hat Ärger mit den Saberon und wir können es uns nich' leisten, noch mehr Leute hinzuschicken. Aber ich hab 'ne Idee.\n\nAn der Westküste von Gorgrond lebt 'n riesiger Wurm, den wir Beben nennen – oder auch Verschlinger von Hummerstroks, weil er so gefräßig is'. Wenn Ihr dieses Vieh tötet und einen Batzen Hummerstrokfleisch mitbringt, können wir das Zeug hier kochen und dann zu unser'm Außenposten bringen. So halten wir uns die Saberon 'n Weilchen vom Hals!", sourceObjective = "Tötet Beben westlich von Gorgoreks Sturz in Gorgrond und beschafft einen Haufen halb verdautes Hummerstrokfleisch.", progress = "Grüße, Kommandant.\n\nWas stinkt'n da so übel?", completion = "Das is' genau das, was wir brauch'n, Kommandant. Ich schick das Zeug gleich zu unser'm Koch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37818] = { id = 37818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmlord Ik'rix muss sterben!", description = "Wir ham 'ne ganz neue Methode entwickelt, Waffen zu härten. Wir nehm'n dafür den Panzer von Eisverheerern. Ihre eisigen Panzer eignen sich bestens für den Prozess.\n\nAn den Südwindklippen ganz in der Nähe lebt Schwarmlord Ik'rix – unsre Leute behaupten, er sei der größte Verheerer, den sie jemals geseh'n ham. Wenn Ihr uns seinen Panzer bringt, könnten wir daraus alles Mögliche machen!", sourceObjective = "Besorgt den Eisbrecherpanzer von Schwarmlord Ik'rix an den Südwindklippen am Frostfeuergrat.", progress = "Tach, Kommandant. Was kann ich heute für Euch tun?", completion = "Sehr gut. Das is' genau das, wonach wir gesucht ham!", sourceObjectiveStatus = "unverified-source-field" }
quests[37819] = { id = 37819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen beim Dunkelmond-Rennen", description = "Das ist Euer erstes Rennen, richtig? Keine Sorge – es ist einfacher, als es aussieht. Ich erklär's Euch:\n\nIhr lauft durch dieses große Banner dort, damit setzt Ihr alles in Gang. Danach folgt Ihr den kleineren Bannern, bis Ihr eine große blaue Markierung seht. Berührt sie und lauft dann wieder hierher zurück.\n\nDie Wertung geht nach Zeit, also beeilt Euch! Und passt auf diese elektrischen Stolperdrähte auf. Wenn Ihr da drüber lauft, verliert Ihr wertvolle Sekunden. Viel Glück!", sourceObjective = "Rennt durch die Startposition des Dunkelmond-Rennens, berührt die blaue Markierung und kehrt dann zur Startposition des Dunkelmond-Rennens zurück.", progress = "Schnell zur blauen Markierung!", completion = "Ihr habt es geschafft! Das ist nur ein Trainingsrennen, Eure Zeit taugt also nur, um bei Freunden anzugeben.\n\nIch würde sagen, es ist Zeit für die große Sause!", sourceObjectiveStatus = "unverified-source-field" }
quests[37820] = { id = 37820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecoil Reinforcements" }
