quests[37833] = { id = 37833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 010 - Offerings To Elune" }
quests[37834] = { id = 37834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugel der Herrschaft", description = "Gul'dan und der Schattenrat haben vollständige Kontrolle über Garonas Seele. Wir haben versucht, ihr mit traditionellen Zaubermethoden zu helfen, aber ohne Erfolg. Jetzt ist es Zeit, etwas Unorthodoxes auszuprobieren.\n\n<Khadgar knackt mit den Fingern. Seine Augen leuchten voller verstörender Vorfreude.>\n\nIch habe gerade von einer Basis des Schattenrats erfahren, die unter der Draeneistadt Elodor verborgen ist. Dort kontrolliert der Schattenrat Spione mithilfe einer Kugel der Herrschaft. Greift die Höhle an und beschafft mir die Kugel! Diese dunkle Magie werden wir zu unserem Vorteil nutzen.", sourceObjective = "Findet eine Kugel der Herrschaft in der Höhle der Geheimnisse im Schattenmondtal.", progress = "<Khadgars Finger leuchten schon erwartungsvoll.>\n\nDie Kugel! Habt Ihr sie gefunden?", completion = "Reicht sie mir... Achtung, vorsichtig. Ah, spürt ihr das? Es jagt mir einen kalten Schauer über den Rücken. Sie beobachtet uns, {name}.\n\nDas heißt, ich habe jetzt den Schattenrat in mein Haus eingeladen. Bringen wir das hier hinter uns, bevor dieses Ding noch Schaden anrichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[37835] = { id = 37835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenkrieg", description = "Der Schattenrat ist weitaus etablierter, als Ihr dachtet. Eine große Zahl seiner Mitglieder scheint darauf abzuzielen, den Exarchenrat der Draenei in der oberhalb gelegenen Stadt zu unterwandern.\n\nKhadgar würde sich sicherlich nicht darüber beschweren, wenn Ihr diesen Plan im Gegenzug ein wenig... unterwandert.", sourceObjective = "Tötet 15 Mitglieder des Schattenrats in der Höhle der Geheimnisse.", completion = "Gut gemacht, {name}! Ich finde es sehr beunruhigend, dass sich der Schattenrat selbst in dieser abgelegenen Region von Draenor etabliert hat. Gul'dan war gewiss nicht untätig.", sourceObjectiveStatus = "unverified-source-field" }
quests[37836] = { id = 37836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außer Kontrolle", description = "Es ist an der Zeit, Garona zu befreien. Ich weiß nun, was ich tun muss... ich glaube es zumindest. Für den Fall, dass etwas schiefgeht, möchte ich, dass Ihr in meiner Nähe bleibt.\n\nLasst mich wissen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Khadgar und steht ihm zur Seite, während er Garona aus Gul'dans Gedankenkontrolle befreit.", completion = "Garona ist noch sehr mitgenommen, aber sie ist nun auf unserer Seite. Sie kann es kaum erwarten, an ihrem früheren Meister Rache zu üben!\n\nIch denke, es ist im Bereich des Möglichen, dass ich ihr die Messerattacke auf meine Person vergeben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[37837] = { id = 37837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona, übernehmen Sie", description = "Wenn Garonas Berichte stimmen, dann hält sich Gul'dan auf dem Gelände dieses Kommandopostens der Eisernen Horde auf. Begebt Euch mit Garonas Hilfe ins Innere des Kommandopostens, sammelt sämtliche Informationen, die Ihr finden könnt, und findet heraus, was Gul'dan vorhat.\n\nDie Wachen sind in höchster Alarmbereitschaft. Garona kann einzelne Wachen für Euch \"liquidieren\", aber dabei darf sie niemand beobachten! Ihr müsst Euch Eure Ziele sorgfältig aussuchen und Euch so unbemerkt Euren Weg durch die Bastion bahnen. Lasst nicht zu, dass jemand Alarm schlägt.\n\nWenn es da drinnen zu heiß wird, werde ich Euch in Sicherheit teleportieren. Oder... ich werde es zumindest versuchen.", sourceObjective = "Infiltriert mit Garonas Hilfe Klingenwuts Kommandoposten. Setzt Ihre Talente geschickt ein, um die Wachen zu eliminieren, ohne bemerkt zu werden. Sucht nach Geheimdienstinformationen der Eisernen Horde und spioniert Gul'dan aus.", completion = "Gut gemacht!\n\nGul'dan ist noch viel schwieriger zu fassen, als ich dachte. Er hat hinter den Kulissen seine Macht ausgedehnt und nun da wir seine Feinde geschwächt haben, hat er die Situation ausgenutzt, um die Kontrolle über die Überreste der Eisernen Horde zu übernehmen.\n\nWir müssen unsere nächsten Schritte planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37838] = { id = 37838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Garona", sourceObjective = "{class}, ich weiß, dass ich nicht viel dafür getan habe, Euer Vertrauen zu gewinnen. Bis zu dem Zeitpunkt meiner Befreiung hat mein Leben nicht mir gehört.\n\nEure Beharrlichkeit und die Weisheit Eures Erzmagiers haben mich erlöst. Ihr habt an mich geglaubt, als ich selbst nicht an mich geglaubt habe. Ihr habt mir mein Leben zurückgegeben, und nun gebe ich es aus freien Stücken in Eure Hände. Ich werde Euch hier auf Draenor bis an mein Lebensende dienen.\n\nZeigt mir Eure Feinde und ich werde ihnen ein schnelles und lautloses Ende bereiten... Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37839] = { id = 37839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möge das Licht mit Euch sein", description = "Ihr habt alles vollbracht, um was ich Euch gebeten habe, {name}. Ich denke, wir können Eurem Ring eine letzte Verzauberung verleihen. Doch... dabei müssen wir sehr vorsichtig sein. Als ich das letzte Mal Euren Ring verstärkt habe, hat Euch das getötet. (Entschuldigung.) Wir benötigen göttliche Unterstützung, um Euch weitere Macht zu verleihen.\n\nGlücklicherweise habt Ihr Euch während Eurer Zeit an diesem Ort mächtige Verbündete gefunden. Reist zum Tempel von Karabor, Yrel wird dort auf Euch warten. Mit dem Segen eines Naaru wird Euer Ring so mächtig und einzigartig sein, wie – nun, wie Ihr selbst. Geht nach Karabor. Ihr habt es Euch verdient.", sourceObjective = "Trefft Euch mit Yrel am Kolosseum des Lichts in der Nähe des Tempels von Karabor.", completion = "Das habt Ihr Euch verdient, {class}. Ihr habt meine Welt ausführlich bewandert. Habt unvorstellbare Hindernisse überwunden und befandet Euch Auge in Auge mit uralten Bestien, düsterer Magie und schrecklicher Maschinerie. Immer wieder habt Ihr meinem Volk mit Eurer Geduld und Tapferkeit als Vorbild gedient.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37840] = { id = 37840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen Draenors", description = "Ihr habt alles vollbracht, um was ich Euch gebeten habe, {name}. Ich denke, wir können Eurem Ring eine letzte Verzauberung verleihen. Doch... dabei müssen wir sehr vorsichtig sein. Als ich das letzte Mal Euren Ring verstärkt habe, hat Euch das getötet. (Tut mir leid!) Ich werde ein uraltes Stück Magie verwenden, um ihn noch weiter aufzuwerten.\n\nGlücklicherweise habt Ihr während Eures Aufenthaltes hier ein paar mächtige Verbündete gefunden. Sucht Scharfseher Drek'Thar am Thron der Elemente in Nagrand auf. Dort könnt Ihr den Segen der Elemente erhalten und gefahrlos die finale Form des Rings offenbaren. Geht! Holt Euch Eure Belohnung!", sourceObjective = "Sprecht mit Drek'Thar am Thron der Elemente in Nagrand.", completion = "Das habt Ihr Euch verdient, {class}. Ihr habt diese Wildnis ausführlich bewandert. Habt unvorstellbare Hindernisse überwunden und befandet Euch Auge in Auge mit uralten Bestien, düsterer Magie und schrecklicher Maschinerie. Immer wieder habt Ihr mich mit Geduld und Tapferkeit überrascht.\n\nIch danke Euch, {name}. Ich bin stolz darauf, Euch als Freund zu bezeichnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37841] = { id = 37841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Vorstoß", description = "Unsere Kampagne in Draenor hat eine unerwartete Wendung genommen. Jetzt, wo Gul'dan seine Macht über die Eiserne Horde ausübt, wird sich die Geschichte wiederholen – unsere Welt ist mehr denn je in Gefahr.\n\nEs ist an der Zeit, die ganze Macht Eurer Garnison in den Kampf gegen den Tanaandschungel zu werfen. Baut eine Schiffswerft für Eure Garnison auf! Ich werde Euch dann bei Eurer neuen Werft treffen, damit wir die nächsten Schritte besprechen können.", sourceObjective = "Sprecht mit dem Fraktionsführer in Eurer Garnison und schließt die Quests zum Bau einer Schiffswerft ab. Khadgar wird zu Euch kommen, wenn sie fertig ist.", completion = "So sieht man sich also wieder.\n\nDa Ihr nun die Werft erbaut habt, sollten wir uns über die nächsten Schritte unterhalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[37842] = { id = 37842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Yaeger-367" }
quests[37848] = { id = 37848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Amulett von Rukhmar", description = "Den Jüngern von Rukhmar scheinen Informationen in die Hände gefallen zu sein, die zu einem uralten Amulett führen. Angeblich soll es die Macht ihres Gottes besitzen und diese auf den Träger übertragen. Wir dürfen nicht zulassen, dass sie an dieses Amulett gelangen.\n\nBegebt Euch nach Skettis und bringt in Erfahrung, was sie herausgefunden haben. Wir müssen es vor ihnen finden.", sourceObjective = "Durchsucht die Ruinen vom oberen Skettis nach Aufzeichnungen der Arakkoa über das Amulett von Rukhmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[37849] = { id = 37849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett von Rukhmar: Der erste Schlüssel", description = "In den Aufzeichnungen der Arakkoa ist die Rede von drei \"Schlüsseln\", die aktiviert werden müssen, um die Apexismaschine zu benutzen. Der erste von ihnen befindet sich in Skettis. Der Text dazu lautet:\n\n\"Der erste Schlüssel wird in den Höhen des oberen Skettis aufbewahrt, dort, wo die Toten ihn vor den Klauen der Unerwünschten beschützen.\"", sourceObjective = "Findet und aktiviert den ersten Schlüssel zur Apexismaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[37850] = { id = 37850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett von Rukhmar: Der zweite Schlüssel", description = "Der erste Punkt wurde aktiviert, es bleiben noch zwei. In den uralten Aufzeichnungen der Ausgestoßenen gibt es Hinweise über den Verbleib des zweiten Schlüssels:\n\n\"Unter dem dritten Wasserfall des mächtigen Skettisstroms liegt der zweite Schlüssel versteckt. Mögen seine rauschenden Wasser diejenigen mit sich reißen, die danach suchen.\"", sourceObjective = "Findet und aktiviert den zweiten Schlüssel zur Apexismaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[37851] = { id = 37851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett von Rukhmar: Der letzte Schlüssel", description = "Es fehlt nur noch ein letzter Schlüssel, um die Apexismaschine verwenden zu können. In den Aufzeichnungen wird beschrieben, wo er liegt:\n\n\"Der letzte Schlüssel liegt tief im Inneren der Fungushöhlen, in die der Fluss schließlich mündet. Ihre widerwärtigen Bewohner, die fahlen Orcs, sind eine ausgezeichnete Abschreckung.\"", sourceObjective = "Findet und aktiviert den letzten Schlüssel zur Apexismaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[37852] = { id = 37852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett von Rukhmar: Die Apexismaschine", description = "Die Schlüssel wurden aktiviert. Ihr könnt jetzt die Apexismaschine benutzen, die zu dem Amulett führt.\n\nDen Aufzeichnungen der Arakkoa zufolge befindet sie sich wahrscheinlich im Vergessenen Anzuversteck, im \"Schrein des Rabengotts\".", sourceObjective = "Aktiviert die Apexismaschine und bringt das Amulett von Rukhmar in Euren Besitz.", progress = "Wart Ihr erfolgreich? Konntet Ihr den Arakkoa das Amulett entreißen?", completion = "Ich bin erleichtert, dass die Jünger von Rukhmar das nicht in ihre Klauen bekommen haben. \n\nIch werde es sofort zu Dr. Jones senden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37853] = { id = 37853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod des Ältesten", description = "Ich werde tun, was ich kann, um ihn zu stabilisieren, aber ich brauche Eure Hilfe.\n\nDie wenige Energie, die ihm verbleibt, bezieht er aus dem Manateich, in dem er liegt.\n\nMacht es dem Welpling nach. Wenn wir Leykristalle in den Teich werfen, bezieht er daraus etwas Energie und somit noch ein wenig mehr Lebenszeit.\n\nSie scheinen diese Kristalle aus der Höhle im Norden zu beziehen.", sourceObjective = "Tötet Leywürmer, um 6 knisternde Leywurmkerne zu beschaffen, und werft sie dann in Senegos' Teich.", progress = "Es klingt vielleicht naiv, aber ich hatte immer gedacht, dass Großvater für immer bei uns sein würde.", completion = "Ich danke Euch. Eure Mühen lindern seine Schmerzen.\n\n<Sie seufzt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37855] = { id = 37855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Letzte seiner Art", description = "Wir brauchen Hilfe.\n\nNach Todesschwinges Tod haben wir Drachen fast all unsere Kraft verloren. Und was noch schlimmer ist: Wir können keine Eier mehr legen.\n\nMeine Welplinge sind die letzten ihrer Art.\n\nIch brauche Euch jetzt, Champion. Helft mir, meinen Welpenhort zu verteidigen. Dann werden die Blauen Euch zur Seite stehen, wenn Ihr sie braucht, das schwöre ich.", sourceObjective = "Untersucht den Welpenhort der Azurschwingen.", completion = "Keine Sorge, kleines Wesen. Ich bin immer noch in der Azurschwingenrast und liege in meinem Teich.\n\nEs braucht nicht viel Energie, um meine Abbilder hierhin und dorthin zu schicken. Ich bin vielleicht alt und dem Tode nah, aber ich bin immer noch ein blauer Drache.", sourceObjectiveStatus = "unverified-source-field" }
quests[37856] = { id = 37856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verdorrten", description = "Die Verdorrten sind widerwärtige und gefährliche Kreaturen. Sie greifen sich unsere Welplinge, schlagen sie bewusstlos und saugen das Mana aus den wehrlosen Babys.\n\nNormalerweise würden unsere Drachen und Wächter sie vertreiben. Aber heute brauchen wir vielleicht Eure Hilfe.", sourceObjective = "Tötet 12 Verdorrte im Welpenhort der Azurschwingen.", completion = "Ihr habt zwölf Verdorrte zur Strecke gebracht? Sehr gut.\n\nDas sollte ausreichen, um sie ein paar Monate fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37857] = { id = 37857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runas kennt den Weg", description = "Ich weiß zwar nicht, was ich getan habe, dass Ihr mich umbringen wolltet, aber ich möchte trotzdem Wiedergutmachung leisten.\n\nHm... Euer Drache beklagt sich über seine Schwäche. Ich kenne den Grund dafür. Runas kann das in Ordnung bringen, <mein Freund/meine Liebe>.\n\nIn meinem Volk gibt es jemanden, der direkt aus dem Boden von Azsuna Leyenergie bezieht. Sein Name ist Ael'Yith. Ich kann Euch zu seinen Manakondensatoren bringen.\n\nEs ist nicht zu spät, den von den anderen verursachten Schaden wiedergutzumachen. Ihr habt recht daran getan, mir zu vertrauen.", sourceObjective = "Gestattet Runas, Euch zu begleiten.", progress = "Ich traue ihm trotzdem nicht.", completion = "Sie zapfen die Leylinien an?", sourceObjectiveStatus = "unverified-source-field" }
quests[37858] = { id = 37858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellagosa", description = "Irgendetwas stimmt hier nicht, {name}.\n\nIch habe Stellagosa ausgesandt, um Euch zu helfen, aber ich kann sie nicht mehr spüren.\n\nBitte geht und findet heraus, was meiner Enkelin zugestoßen ist.", sourceObjective = "Sucht nach Stellagosa.", completion = "...So viele von ihnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[37859] = { id = 37859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgezehrten", description = "<Der Welpling ist am Leben, aber ohnmächtig. Einer der Verdorrten muss schon sein Mana abgesaugt haben.>\n\n<Ihr wisst bereits, dass freigelegte Leykristalle eine geringe Menge Energie bergen. Vielleicht könnt Ihr einen dieser Kristalle verwenden, um ein paar Welpen wiederzubeleben.>", sourceObjective = "Findet einen trüben Leykristall und holt dann 10 manageschröpfte Welplinge ins Leben zurück.", progress = "Das war clever, {race}. Ja, ein Leykristall könnte ihre Sinne wiederbeleben.", completion = "Ich stehe tief in Eurer Schuld, {name}.\n\nEinem geschwächten alten Drachen wie mir zu helfen, ist schon wahrlich tapfer. Aber meine Welplinge und damit unsere gesamte Blutlinie zu retten?\n\nIch werde Euch jetzt nach Kräften in Eurer Sache unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37860] = { id = 37860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klaue wäscht die andere", description = "Viel besser. Ich wusste, dass ich auf Euch zählen kann, <mein Freund/meine Gute>. Und jetzt möchte ich mich mit einem Gefallen revanchieren.\n\nIch weiß, wie Ihr die großen Manasammlerpylonen zerstören könnt. Es gibt noch Hoffnung für Euren großen Drachen!\n\nDie Pylonen sind nur gegen Angriffe vom Boden, aber nicht aus der Luft geschützt. Lasst die Welplinge auf sie los. Im Gegensatz zu uns können sie fliegen.\n\nVertraut mir.", sourceObjective = "Lasst die Welplinge auf alle Manasammlerpylonen in Zarkhenar los.", sourceObjectiveStatus = "unverified-source-field" }
quests[37861] = { id = 37861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Prinz der Nachtgeborenen", description = "<Senegos wirkt konzentriert.>\n\nIch kann es jetzt spüren. In dem zerstörten Gebäude im Osten. Einer dieser Narren muss die Leylinie angezapft haben.\n\nIch gehe davon aus, dass er schwer bewacht wird, {name}. Nur zur Erinnerung: Das Schicksal meiner Brut liegt in Euren Händen.", sourceObjective = "Tötet Ael'Yith.", completion = "Er mag nicht tot sein, doch zumindest ist er fort.\n\nOhne ihren Anführer sollten die stumpfsinnigen Verdorrten sich bald zerstreuen und aussterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37862] = { id = 37862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch am Leben", description = "Wartet, was habe ich gehört? War es... \"Labt Euch an den Drachen\"? Wir müssen gleich Großvater fragen!\n\nSagt Bescheid, wenn Ihr zum Aufbruch bereit seid.", sourceObjective = "Sprecht mit Stellagosa über einen Flug zurück zur Azurschwingenrast.", completion = "Nein... Wir sind zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[37864] = { id = 37864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidtalon of the Dark Star" }
quests[37865] = { id = 37865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Eisenfausthafen" }
quests[37866] = { id = 37866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Eisenfausthafen" }
quests[37867] = { id = 37867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystalbeard" }
quests[37868] = { id = 37868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein großes Rennen!", description = "Ihr habt Spaß an so einem Rennen, stimmt's? Ich auch!\n\nDas Rennen besteht aus vier Etappen – rennt zuerst zur violetten Markierung, dann zur grünen, dann zur roten und dann zurück hierher.\n\nDie Wertung geht nach Zeit, also beeilt Euch!", sourceObjective = "Lauft von der Startposition zur violetten Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition.", progress = "Ihr habt nicht alle Markierungen berührt. Beeilt Euch!", completion = "Gut gemacht und gute Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37869] = { id = 37869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggerbeak" }
quests[37881] = { id = 37881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Explosive Entdeckungen", description = "In einer Höhle irgendwo im Schattenmondtal soll ein altes Buch versteckt sein, das mächtige Geheimnisse enthält. Dieses Buch könnte uns bei unserem Kampf gegen die Eiserne Horde von Nutzen sein, doch leider ist der Eingang der Höhle von einer uralten Barriere aus arkaner Energie geschützt.\n\nEin Goblin im Nachtflutnest behauptet zu wissen, wie man jede Barriere beseitigt. Überzeugt ihn, Euch seine Geheimnisse zu verraten, und bringt das Buch zurück.", sourceObjective = "Besiegt Sprengmeister Megakrach im Nachtflutnest und nehmt sein Sprengstoffkochbuch an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37882] = { id = 37882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Zauberfoliant: Die erste Zutat", description = "Megakrachs \"arkaner Panzerknacker\" sollte die Barriere zerstören können. Für diesen Spezialsprengstoff benötigt Ihr drei Zutaten. Die erste Zutat, Präzisionssprengpulver, findet Ihr ganz in der Nähe. Im Buch steht:\n\n\"Für die Herstellung benötigt Ihr zunächst etwas hochwertiges Präzisionssprengpulver. Hier bei Rußschmied & Co. ist dieses Pulver relativ einfach zu beschaffen, da es für alle Kanonen verwendet wird.\"", sourceObjective = "Folgt den Hinweisen in Megakrachs Kochbuch, um Präzisionssprengpulver zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37883] = { id = 37883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Zauberfoliant: Die zweite Zutat", description = "Ihr habt das Sprengpulver, jetzt braucht Ihr noch einen passenden Zünder. Eine Notiz neben dem Eintrag im Kochbuch gibt Hinweise darauf, wo Ihr einen Zünder finden könnt:\n\n\"Nicht vergessen: Mehr Hochspannungszünder bestellen. Die letzte Ladung ging vor der Küste des Schattenmondtals verloren, in der Nähe der von Dämonen bewohnten Klippen. Vielleicht sollten wir Taucher rausschicken, um sie zu bergen.\"", sourceObjective = "Folgt den Hinweisen in Megakrachs Kochbuch, um den Hochspannungszünder zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37884] = { id = 37884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Zauberfoliant: Die letzte Zutat", description = "Die letzte Zutat für Megakrachs Bombe ist eine beträchtliche Menge an Dämonenblut. \n\nLeider werden die Dämonen ihr Blut nicht freiwillig hergeben...", sourceObjective = "Sammelt Blut von Dämonen auf Socrethars Klippe.", sourceObjectiveStatus = "unverified-source-field" }
quests[37885] = { id = 37885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Zauberfoliant: Die Barriere durchbrechen", description = "Ihr habt die Bestandteile gesammelt und einen \"arkanen Panzerknacker\" hergestellt.\nDieser Sprengsatz hat hoffentlich genug Wucht, um die Barriere zu zerstören.\n\nEs gibt nur einen Weg, das herauszufinden...", sourceObjective = "Zerstört die uralte Barriere unterhalb von Socrethars Klippe und nehmt den Foliant der namenlosen Leere an Euch.", progress = "Dr. Jones hat mich gebeten, dieses Buch von Euch entgegenzunehmen, aber ich bin mir nicht sicher, ob ich es berühren möchte.", completion = "Ich werde das an Dr. Jones übergeben.\n\nEhrlich gesagt bin ich froh, wenn ich es los bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[37886] = { id = 37886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ironhold" }
quests[37887] = { id = 37887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[37888] = { id = 37888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Solo" }
quests[37889] = { id = 37889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Tanaan", description = "Es ist vollbracht! Auf Euren Befehl haben wir unser erstes Schiff fertiggestellt und können unsere Operationen von hier aus starten.\n\nNun da wir einen Truppentransporter haben, können wir Durotan und Euren Erzmagier wissen lassen, dass die Invasion von Tanaan beginnen kann. Sprecht an den Docks mit ihnen, um abzulegen.", sourceObjective = "Trefft Euch mit Khadgar und sprecht dann mit Draka, um die Invasion zu starten.", completion = "Die Landung war einfacher, als ich erwartet hatte, aber vor uns liegt Ärger.", sourceObjectiveStatus = "unverified-source-field" }
quests[37890] = { id = 37890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hindernislauf", description = "Es ist seltsam, dass diese Docks von der Eisernen Horde verlassen worden sind, aber unsere Späher berichten, dass uns Ärger erwartet.\n\nEine Plündererbande des Blutenden Auges durchsucht die verlassenen Gebäude nordwestlich von hier.\n\nWeiter unten an der Straße sind orcische Kultisten, die... irgendetwas... in der Nähe des Dunklen Portals veranstalten.\n\nWir sollten versuchen, Befehle oder Informationen zu den Vorgängen hier sicherzustellen, und uns dann mit unseren Spähern treffen.", sourceObjective = "Sucht nach Informationen zu den in dem Gebiet befindlichen Streitkräften und trefft Euch anschließend mit den Spähern.", completion = "Gut, zu hör'n, dass die Straße jetzt sicherer is', aber da gibt's noch'n anderes Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[37891] = { id = 37891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Eisenfausthafen", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", completion = "Willkommen zurück, Kommandant. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37892] = { id = 37892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[37908] = { id = 37908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Ernstenbok" }
quests[37909] = { id = 37909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbringer Mox'na" }
quests[37910] = { id = 37910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Sause", description = "Okay, Dunkelmond-Renner, zeigt, was Ihr draufhabt!\n\nDie große Sause besteht aus vier Etappen – lauft von der Startposition zur blauen Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition.\n\nDie Wertung geht nach Zeit, also beeilt Euch!", sourceObjective = "Lauft von der Startposition zur blauen Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition.", progress = "Ihr habt nicht alle Markierungen erreicht. Beeilt Euch!", completion = "Gut gemacht und gute Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37911] = { id = 37911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ganz große Sause", description = "Das hier wird eine richtige Herausforderung! Viel Glück!\n\nDieses Rennen besteht aus vier Etappen: Lauft von der Startposition zur violetten Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition.\n\nDie Wertung geht auf Zeit, also beeilt Euch!", sourceObjective = "Lauft von der Startposition zur violetten Markierung und von dort aus zur grünen, zur roten und schließlich zurück zur Startposition.", progress = "Ihr habt nicht alle Markierungen erreicht. Beeilt Euch!", completion = "Gut gemacht und gute Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[37914] = { id = 37914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Der Weise der Donnerfürsten", description = "Im Frostfeuergrat soll ein Weiser der Donnerfürsten namens Argoram den Ort entdeckt haben, an dem ein sagenumwobenes Relikt versteckt liegt – eine Waffe, die die Orcs unter dem Namen Gronnfänger kennen. \n\nArgoram wurde zuletzt auf dem Weg nach Magnarok gesehen. Findet ihn und lasst Euch von ihm zu diesem Relikt führen.", sourceObjective = "Findet den Weisen der Donnerfürsten Argoram in Magnarok.", sourceObjectiveStatus = "unverified-source-field" }
quests[37916] = { id = 37916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnfänger: Der zerbrochene Speer", description = "Als Ihr in Argorams Tagebuch blättert, wird Euch klar, dass die Bergung dieses Relikts weitaus schwieriger wird, als einfach nur die einzelnen Teile des Speers zu finden.\n\nDer beste Ausgangspunkt für die Suche scheint dort zu sein...", sourceObjective = "Sucht in Magnarok nach der Spitze, dem Schaft und dem Gegengewicht von Gronnfänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[37917] = { id = 37917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnfänger: Der Segen des Feuers", description = "Die Waffe wurde zusammengesetzt, doch fehlt ihr die Macht, die sie einst zu einer Legende machte. Ihr benötigt drei Segnungen, um diese Macht wiederherzustellen: den Segen des Feuers, den Segen des Frosts und den Segen der Wildtiere.\n\nDer erste Segen, der in dem Tagebuch erwähnt wird, ist der Segen des Feuers. Ihr findet dazu folgenden Eintrag:\n\n\"Er beschrieb einen uralten Monolithen, der vom Rand eines Abgrunds über die Klippe ragt, dort wo feuriges Magma sich ins Meer ergießt. Ich glaube, dass der Ort, von dem er spricht, sich gleich über Tor'goroths Zahn befindet.\"", sourceObjective = "Folgt dem Hinweis, um den glühenden Schamanenstein zu finden und den Segen des Feuers zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37918] = { id = 37918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnfänger: Der Segen des Frosts", description = "Die Waffe ist vom Segen des Feuers erfüllt und bezieht ihre Energie aus dem glühenden Schamanenstein. Der gefrorene Schamanenstein sollte den nächsten Segen verleihen. Argoram erwähnt in seinem Tagebuch, wo dieser sich befindet:\n\n\"Als ich den großen Felsbrocken auswich, die die Ogronschläger nach mir warfen, konnte ich auf dem höchsten der schneebedeckten Türme etwas erblicken, was wie ein weiterer Monolith aussah. Möglicherweise ist es der gefrorene Schamanenstein, von dem angenommen wird, dass er den Segen des Frosts verleiht.\"", sourceObjective = "Folgt dem Hinweis, um den gefrorenen Schamanenstein zu finden und den Segen des Frosts zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37919] = { id = 37919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnfänger: Der Segen der Wildtiere", description = "Gronnfänger pulsiert nun mit der Kraft des Feuers und des Frosts. Es fehlt nur noch der Segen der Wildtiere, um der Waffe wieder ihre frühere Macht zu verleihen. Argoram hat geglaubt, dass die Waffe dafür mit dem Blut der schwarzen Rylaks der Steinzornklippen geweiht werden muss. In seinem Tagebuch findet sich dazu folgender Eintrag:\n\n\"Oben auf den Steinzornklippen habe ich einen Altar gesehen, auf dem die Oger diesen uralten Kreaturen Opfergaben dargebracht haben. Vielleicht könnte ich so eine von ihnen anlocken.\"", sourceObjective = "Besiegt den uralten schwarzen Rylak und taucht Gronnfänger in sein Blut.\n\nBringt die Waffe zu Bodrick Grau zurück, wenn Ihr sie mit Macht erfüllt habt, um Eure Belohnung zu erhalten.", progress = "Seid Ihr mit dem Relikt der Donnerfürsten zurückgekehrt?", completion = "Wer hätte gedacht, dass ein so unscheinbarer Speer einen ausgewachsenen Gronn zu Fall bringen kann?\n\nIch bin mir sicher, Dr. Jones wird sich freuen, das seiner Sammlung hinzuzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37921] = { id = 37921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten an den Docks", description = "Unser Bergungsteam glaubte, dass diese Docks hier verlassen seien. Aber hier wimmelt es nur so von Überresten der Eisernen Horde. Gul'dans Schergen verwandeln alle, die nicht rechtzeitig fliehen können, und schaffen sie rüber in den Tanaandschungel.\n\nKommandant, wenn Ihr die Feinde hier ausräuchert, kann mein Team einige Teile der Ausrüstung retten.\n\nUnd außerdem ist jeder Orc weniger eine Sorge weniger in Tanaan!", sourceObjective = "Tötet 1 Orcs der Eisernen Horde und 50 Ogron.", sourceObjectiveStatus = "unverified-source-field" }
quests[37924] = { id = 37924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maritime Bergungsgüter", description = "Das Ganze würde um einiges schneller gehen, wenn Ihr bei Eurer kleinen Aufräumaktion alle größeren Vorratskisten markiert, auf die Ihr stoßt.\n\nBringt diese Fahne an, dann schick' ich direkt einen meiner Leute vorbei, der sich um den Rest kümmert!", sourceObjective = "Markiert 7 Vorratskisten mit einer Fahne.", sourceObjectiveStatus = "unverified-source-field" }
quests[37928] = { id = 37928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Normantis the Deposed" }
quests[37932] = { id = 37932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound Rift" }
quests[37933] = { id = 37933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdeckung der Artefaktfragmente", description = "Die Artefaktfragmente scheinen von Kreaturen zu stammen, die wir in den Außenbezirken von Ashran gefunden haben. Geht und tötet alle, die Ihr findet, und bringt mindestens fünf zu Ecilam dem Magier am Lagerfeuer in der Sturmschildfeste.", sourceObjective = "Harrison Jones in der Sturmschildfeste möchte, dass Ihr Kreaturen in den Außenbezirken von Ashran abseits der Hauptstraße tötet und 5 Artefaktfragmente zu Ecilam bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37934] = { id = 37934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein, durch und weiter!", description = "'n paar von uns konnt'n durchschleichen, aber dann wurd'n wir entdeckt, un' die Kanonen hab'n angefang'n zu feuern. Die kleinen sin' kein Problem, aber die große... Wir müss'n sie ausschalt'n, wenn wir irgendwas durchbring'n woll'n.", sourceObjective = "Zerstört die teuflische Verteidigungskanone, die dem Tor Deckung gibt.", completion = "Wir bring'n jetzt Vorräte hier durch. Haben 'nen guten Bauplatz gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[37935] = { id = 37935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angriffsbasis", description = "In der Nähe gibt's 'nen guten Platz. Nich' zu dicht am Feind, aber dicht genug, dass wir die Jungs im Westen unter Druck setz'n könn'n. Folgt mir.", sourceObjective = "Errichtet Eure Angriffsbasis im Tanaandschungel.", completion = "Das war der leichte Teil, jetzt wird's schwieriger.", sourceObjectiveStatus = "unverified-source-field" }
quests[37937] = { id = 37937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Varyx the Damned" }
quests[37938] = { id = 37938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Ruinen von Kra'nak" }
quests[37939] = { id = 37939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ruins of Kra'nak" }
quests[37940] = { id = 37940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Eisenfausthafen", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", completion = "Die Späher haben schon von Euren Erfolgen berichtet.\n\nLok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[37941] = { id = 37941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Der befallene Orc", description = "Die Orcs des Lachenden Schädels in Gorgrond erzählen sich die Legende von Schädelgreifer. Seine Maske, die nur als der schweigende Schädel bekannt ist, hat bei ihnen ebenfalls einen legendären Ruf. Sie könnte uns helfen, mehr über diesen Klan zu lernen.\n\nBis vor kurzem dachte man, Schädelgreifer sei verschwunden. Doch anscheinend wurde er erst kürzlich in der Immergrünen Wildnis gesichtet. Der letzte Orc, der sein, nun ja, Antlitz gesehen hat, fiel den Botani dort zum Opfer, aber vielleicht finden sich dort Hinweise darauf, wie Ihr Schädelgreifer und die Maske finden könnt.\n\nWenn die Botani ihn haben, ist er unter Umständen wenig kooperativ.", sourceObjective = "Findet die Aufzeichnungen des grinsenden Tolg zwischen den mutierten Orcs in der Immergrünen Wildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[37942] = { id = 37942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schweigende Schädel: Die erste Zutat", description = "Der grinsende Tolg war dabei, ein Elixier zu brauen, durch das er mit den Verheerern kommunizieren konnte. Nur mit ihrer Hilfe konnte sich Schädelgreifer so lange versteckt halten.\n\nDie erste Zutat, die Blätter der Schattendistel, gibt es ganz in der Nähe. Im Tagebuch findet Ihr folgenden Eintrag:\n\n\"Sie gedeiht in den Schatten unter der unerbittlichen Sonne Gorgronds. Ich habe einige Exemplare unter den stehenden Steinen in der Nähe des Schwarzeisenwalls gesehen.\"", sourceObjective = "Folgt dem Hinweis aus dem Tagebuch, um Schattendistelblätter zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37943] = { id = 37943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schweigende Schädel: Die zweite Zutat", description = "Die zweite Zutat für das Elixier ist eine Ranke des Knochendorns. Im Tagebuch findet sich folgender Eintrag dazu:\n\n\"Ich brauche eine Ranke des Knochendorns, der in den Knochen lange verwester Kadaver wächst. Ich erinnere mich, das Skelett eines lange verendeten Tiers in einem ausgetrockneten Flussbett in der nördlichen Wildnis gesehen zu haben. Der von der Sonne ausgedörrte Schädel wäre ideal für diese Pflanze.\"", sourceObjective = "Folgt dem Hinweis aus dem Tagebuch, um eine Knochendornranke zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37944] = { id = 37944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schweigende Schädel: Die dritte Zutat", description = "Die letzte Zutat für das Elixier ist eine Handvoll Dampfhutpilze. Im Handbuch findet sich folgender Eintrag:\n\n\"Die Krähenfütterin sagte, dass sie zwischen den Dampfschloten in den höheren Regionen des Immergrünen Flors wachsen. Ich erinner mich, einen solchen Ort oberhalb der Hydrabecken im Norden gesehen zu haben.\"", sourceObjective = "Folgt dem Hinweis aus dem Tagebuch, um Dampfhutpilze zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37945] = { id = 37945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schweigende Schädel: Den Greifer greifen", description = "Ihr habt alle Zutaten gefunden. Sucht jetzt das Lager des grinsenden Tolg in einer Höhle nicht weit von hier, um das Elixier zu brauen. \n\nSobald Ihr das Elixier getrunken habt, solltet Ihr mit den Verheerern in der Gegend kommunizieren können. Mit etwas Glück können sie Euch zu Schädelgreifer führen.\n\nFür seine Maske erwartet Euch eine gewaltige Belohnung.", sourceObjective = "Verwendet das Elixier des Lachenden Schädels, um Schädelgreifer zu finden, und nehmt den schweigenden Schädel an Euch.", progress = "Das muss der verfluchte Schädel sein. Meint Ihr wirklich, wir sollten das Ding berühren?", completion = "Diese Maske unterscheidet sich definitiv von allen Masken des Lachenden Schädels, die ich vorher gesehen habe. Ich bringe sie zu Jones, mal sehen, was er dazu sagt. \n\nEr hat mich gebeten, Euch diese Belohnung zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37946] = { id = 37946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ironhold" }
quests[37947] = { id = 37947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Solo" }
quests[37948] = { id = 37948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifizierer Darkoor muss sterben!", description = "Gurgthock vom Ring des Blutes kam grad vorbei und sagte, dass Mogor seinen Blutchampion in einem speziellen Schaukampf sehen möchte. Damit seid Ihr gemeint, Kommandant!\n\nFlüstert Gurgthock einfach ins Ohr: \"Ich suche den Suchenden\" und er kümmert sich dann um den Rest!", sourceObjective = "Sprecht mit Gurgthock am Ring des Blutes in Nagrand und gewinnt den Schaukampf.", completion = "Die Nachricht Eures epischen Kampfes verbreitet sich wie ein Lauffeuer, Kommandant. Das könnte unsere Beziehungen mit den Ogern in Zukunft verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[37949] = { id = 37949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifizierer Darkoor muss sterben!", description = "Der Goblin Gurgthock kam grad vorbei. Er sagte, dass Mogor seinen Blutchampion in 'nem speziellen Schaukampf sehen möchte. Dafür hat er wohl extra 'ne ziemlich fiese Kreatur aufgetrieben. Und gegen die dürft ihr dann antreten, Kommandant!\n\nWenn Ihr so weit seid, flüstert Gurgthock einfach ins Ohr: \"Ich suche den Suchenden\". Er kümmert sich dann um den Rest!", sourceObjective = "Sprecht mit Gurgthock am Ring des Blutes in Nagrand und gewinnt den Schaukampf.", completion = "Die Nachricht von Euren Taten verbreiten sich bereits wie 'n Lauffeuer. Wenn die Oger vorher keine Angst vor Eurer Macht hatt'n, ham sie die jetzt auf jeden Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[37953] = { id = 37953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sergeant Mor'grak" }
quests[37956] = { id = 37956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Netherstruck Charm" }
quests[37957] = { id = 37957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runas der Geschmähte", description = "Ich konnte mich nicht lange halten, {name}. Ich bin nicht mehr so stark wie früher. Wir brauchen wirklich Eure Hilfe.\n\nEine dieser widerlichen Kreaturen ist mit ein paar meiner Welplingen davongelaufen. Ich habe aber seinen Namen gehört:\n\nRunas.\n\nIch werde überleben. Es ist nicht weit bis nach Hause. Ihr aber seid noch stark. Tötet diesen Runas, bevor er unserer Brut noch weiteren Schaden zufügen kann.", sourceObjective = "Tötet Runas den Geschmähten.", progress = "Ah, Stella. Immer die Erste. Sie ist noch so jung.", completion = "Haltet Euch fern von ihm, {name}.\n\nDiese gefallenen Elfen sind alle gleich: hinterlistig und heuchlerisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37958] = { id = 37958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 011 - Nether Crystal" }
quests[37959] = { id = 37959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewig hungrig", description = "<Runas wirkt nervös.>\n\nIch kann Euch helfen und ich will Euch wirklich helfen, aber ich bin gerade etwas abgelenkt. Seht Euch nur all das reine, ungefilterte, köstliche Mana an...\n\n<Runas gibt sich selbst eine Backpfeife.>\n\nNein! NEIN! Nicht die Beherrschung verlieren!\n\nIch muss nur wieder den Kopf freibekommen. Ja, genau... Ein paar meiner verkommenen Brüder und Schwestern führen Manajuwelen mit sich... für den kleinen Energieschub zwischendurch. Könntet Ihr ein paar davon für mich auftreiben? Dann werde ich Euch zeigen, wie Ihr die Leylinie zurückbekommt.", sourceObjective = "Beschafft 4 aufgeladene Manajuwelen.", progress = "Habt Ihr sie? Bitte sagt mir, dass Ihr sie gerettet habt!", completion = "<Runas zermalmt hektisch die Juwelen und reibt sich den magischen Staub auf Gesicht, Arme und den Nacken.>\n\n<Für einen Moment wirkt er glückselig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37960] = { id = 37960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienmissbrauch", description = "Diese Monster ziehen das Mana direkt aus dem Boden. Das erklärt, warum nicht einmal meine Manateiche meine Schmerzen lindern können.\n\nIch mache mir Sorgen um meine Brut. Ohne die Kraft der Leylinien sind wir gar nichts. Und wenn es so weitergeht, kann ich Euch vielleicht nicht einmal bei der Suche nach dem Gezeitenstein helfen.\n\nHaltet Ausschau nach den Manakondensatoren und bestraft diese schändlichen nachtsüchtigen Elfen, die sie benutzen.", sourceObjective = "Tötet Iskhaneth und Tyndrissen.", progress = "Mit jedem dieser Narren, den Ihr tötet, werde ich selbst stärker.", completion = "Ich fühle mich schon ein bisschen stärker.\n\nDiese Leykondensatoren wären fast mein Ende gewesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[37961] = { id = 37961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Bass", description = "Wisst Ihr, wie wir die Moral unserer Truppen stärken könnten?\n\nDicke Bässe. Fette Beats.\n\nMit anderen Worten: Wir sollten eine Party für unsere Jungs und Mädels schmeißen! Ihr besorgt mir die passende Hardware, und ich bastel daraus eine Anlage, die ganz Draenor erschüttern wird.", progress = "Besorgt einen Bass-Blaster, ein Laz-Tron-Laufwerk, einen phonischen Verstärker, einen F.N.K.-Kondensator und einen Klafter uraltes Holz.", completion = "Das Zeug ist wirklich gut in Schuss. Das meine ich ernst! Ich glaube, damit kann man tatsächlich noch was anfangen. Gebt mir mal eben eine Minute..." }
quests[37963] = { id = 37963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht zu retten" }
quests[37964] = { id = 37964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Gul'dan!", description = "Wir müssen schnell handeln. Garona hat mir erzählt, dass Gul'dan sich bereits in Bewegung gesetzt hat. Er befindet sich auf dem Weg zu Grommash Höllschrei am Pfad des Ruhms.\n\nWir müssen einschreiten, solange unsere Berichte noch frisch und akkurat sind. Beeilt Euch und trefft mich außerhalb von Klingenwuts Kommandoposten im nördlichen Talador. Wir können es nicht mit Gul'dan und der ganzen Eiserne Horde allein aufnehmen.", sourceObjective = "Sprecht mit Erzmagier Khadgar außerhalb von Klingenwuts Kommandoposten im nördlichen Talador.", completion = "Dieser Ort wimmelt nur so von Wachen. Ich weiß nicht, wie Garona so zuversichtlich sein kann.\n\nAber gut, lasst mich Euch in den aktuellen Plan einweihen...", sourceObjectiveStatus = "unverified-source-field" }
quests[37965] = { id = 37965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verderbter Jahrgang" }
quests[37966] = { id = 37966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel von Sha'naar" }
quests[37967] = { id = 37967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Temple of Sha'naar" }
quests[37968] = { id = 37968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel von Sha'naar", description = "Oben in den Hügeln des Tanaandschungels haben die Sargerei einen einstmals heiligen Tempel in einen Hort dämonischer Rituale verwandelt.\n\nWir müssen sie sofort angreifen, bevor sie ihre Rituale vollendet haben. Je länger wir warten, desto stärker werden unsere Feinde.", sourceObjective = "Greift die Sargereitruppen im Tempel von Sha'naar im Tanaandschungel an.", completion = "Willkommen zurück, Kommandant. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37969] = { id = 37969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Jungle - Tracking Quest - Vol'mar Built - JMC" }
quests[37970] = { id = 37970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[37972] = { id = 37972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkämpfe nicht aktiv" }
quests[37973] = { id = 37973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzsuchvertrag: Der Konstrukteur", description = "Ich habe von einem Draeneikonstrukteur namens Maatun gehört, der einen alten draenischen Kristall wieder zusammenfügen wollte. Der Kristall stammt möglicherweise von den Naaru selbst, Maatun nannte ihn den Traum von Argus. \n\nDer Draenei verschwand, nachdem er die Orcs des Schattenmondklans um Hilfe gebeten hatte, bevor diese sich mit der Eisernen Horde verbündeten. Einer Eurer Späher behauptet, in der Nähe des Eingangs zu den Säulen des Schicksals vor kurzem einen Draenei gesehen zu haben, auf den Maatuns Beschreibung passt. Begebt Euch dort hin und versucht mehr herauszufinden.", sourceObjective = "Sucht am Eingang zu den Säulen des Schicksals nach Hinweisen auf den Verbleib von Maatuns Kristall.", sourceObjectiveStatus = "unverified-source-field" }
quests[37974] = { id = 37974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkämpfe nicht aktiv" }
quests[37975] = { id = 37975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkämpfe nicht aktiv" }
quests[37976] = { id = 37976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von Argus: Das erste Fragment", description = "Bei seinem Versuch, den Traum von Argus wieder zusammenzusetzen, nahm Maatun die Hilfe von drei Orcs in Anspruch. Doch diese Orcs betrogen ihn und nahmen die Kristallsplitter an sich, bevor sie zusammengefügt werden konnten. Sucht nach diesen Orcs, vielleicht haben sie die Splitter immer noch.\n\nDas erste Ziel liegt nicht weit von hier. Im Tagebuch findet Ihr folgenden Eintrag:\n\n\"Man hat mir gesagt, dass sie den Großteil ihrer Zeit in der Kristallhöhle nördlich des Lagers verbringt. Sie untersucht die Kristalle dort, um einen Weg zu finden, die in ihnen schlummernden Kräfte zu verbessern.\"", sourceObjective = "Folgt den Hinweisen im Tagebuch, um Lor Steinfaust aufzuspüren. Besiegt sie und nehmt den groben Kristallsplitter an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37977] = { id = 37977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von Argus: Das zweite Fragment", description = "Der zweite Orc, den Matuun erwähnt hat, war ein Runenmeister und Zauberer. Er muss sich irgendwo im Hauptlager aufhalten. Im Tagebuch steht Folgendes:\n\n\"Sie erwähnte, dass der Orc normalerweise in einer der Hütten der Runenmeister im südlichen Teil des Lagers anzutreffen sei. Diese Hütten sind leicht an den ihnen umgebenden Steinsäulen und den darüber schwebenden Runensteinen zu erkennen.\"", sourceObjective = "Folgt den Hinweisen im Tagebuch, um Vok Schwarzzunge aufzuspüren. Besiegt ihn und nehmt den gesprungenen Kristallsplitter an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37978] = { id = 37978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von Argus: Das letzte Fragment", description = "Der letzte Orc, den Ihr finden müsst, ist ein zurückgezogener Einsiedler. Er hat sich von den Schattenmondorcs, die in dem Lager an den Säulen des Schicksals leben, meist fern gehalten, wurde aber oft in den Hügeln darüber gesehen. Im Tagebuch findet sich folgender Eintrag:\n\n\"Man sah ihn aber oft bei den Gräbern auf dem höheren Hügel, der das Lager darunter überschaut. Von dort aus hielt er Zwiesprache mit den verstorbenen Vorfahren und man sagt, dass er deren Gesellschaft der seiner lebenden Brüder bevorzugte.\"", sourceObjective = "Folgt den Hinweisen im Tagebuch, um Koros Seelenspan aufzuspüren. Besiegt ihn und nehmt den glatten Kristallsplitter an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37979] = { id = 37979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von Argus: Wiedergeburt eines Kristalls", description = "Ihr habt alle Splitter gefunden, Ihr könnt sie nun zusammenfügen, um den Traum von Argus wiederherzustellen. Sucht die Maschine, die Maatun in seinem Tagebuch erwähnt hat. Sie soll sich in einer Höhle oberhalb der Festung der Pein befinden.", sourceObjective = "Sucht die Maschine für die Kristallrekonstruktion und setzt mit ihrer Hilfe den Traum von Argus zusammen.", progress = "Konntet Ihr die Stücke des Draeneikristalls zusammenfügen?", completion = "Einfach unglaublich! Wenn ich es nicht besser wüßte, würde ich denken, der Kristall war nie kaputt! \n\nIch bin mir sicher, dass sich Dr. Jones sehr darüber freuen wird, ganz zu schweigen von den Draenei, wenn man den Legenden glaubt, die sich darum ranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[37980] = { id = 37980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 012 - Book Treasure" }
quests[37981] = { id = 37981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der weltberühmte Ring des Blutes!", description = "Hochverehrte/r Faustvirtuose/in,\n\nWenn Ihr das lest, seid Ihr vielleicht hart genug, um im Ring des Blutes in Nagrand der nächste Champion zu werden.\n\nZusammen mit zwei Freunden seid Ihr herzlich eingeladen, gegen die tödlichsten Kreaturen in ganz Gorgrond um Euer Leben zu kämpfen. Ein erfrischend brutales Spektakel, das man gesehen haben muss!\n\nWendet Euch an mich, wenn Ihr bereit für Euren ersten Kampf seid – besiegt vier meiner wildesten Kampfbestien und ich gebe Euch die Gelegenheit, gegen den Titelverteidiger selbst anzutreten!\n\n-Gurgthock", sourceObjective = "Werdet Herr des Rings am Ring des Blutes in Nagrand.", progress = "Zweihundert Gold... zweihundertfünfzig...\n\nDas sind ungefähr dreihundertfünfzig. Nicht übel!\n\nOh, hey, wie isses denn so, Champ?", completion = "Ihr habt es geschafft. Ihr habt es tatsächlich geschafft! Hier ist Eure Belohnung, Champ.\n\nOh Mann, die Oger von Hochfels werden ganz und gar nicht erfreut sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[37982] = { id = 37982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art Tracker - Ashbringer - Tier 0 - Base" }
quests[37983] = { id = 37983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art Tracker - Ashbringer - Tier 1 - Holy" }
quests[37984] = { id = 37984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art Tracker - Ashbringer - Tier 1 - Fire" }
