quests[37990] = { id = 37990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cindral" }
quests[37991] = { id = 37991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agapanthus", description = "<Dieser weibliche Welpling versucht, Eure Aufmerksamkeit zu erregen. Sie schaut Euch in die Augen und deutet dann schnell mit ihrem Kopf in Richtung Nordosten.>", sourceObjective = "Schaut nach den Besuchern in der Azurschwingenrast und bietet Eure Unterstützung an.", completion = "Ich grüße Euch, {class}. Wir könnten Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37992] = { id = 37992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutreks Spalter: Die Geisterschmiede", description = "Jetzt, da alle Teile gefunden wurden, bleibt nur noch eins zu tun: Gutreks Spalter neu zu schmieden. In Goldschaufels Notizbuch wird erwähnt, dass dies nur an dem Ort möglich ist, an dem die Waffe ursprünglich zerlegt wurde.\n\nLaut Notizbuch ist dies in einer \"Geisterschmiede\" geschehen, die sich irgendwo in der Nähe der Schlucht befinden soll. Findet die Schmiede und fügt darauf die Teile zusammen, die Ihr gesammelt habt.", sourceObjective = "Findet die Geisterschmiede in der Donnergrundschlucht und schmiedet Gutreks Spalter neu.", progress = "Is' das die Klinge, die Jones gesucht hat?", completion = "Gute Arbeit, Mann! Ich bring das gleich mal zu Jones. \n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[37993] = { id = 37993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulett von Rukhmar: Die Apexismaschine", description = "Die Schlüssel wurden aktiviert, Ihr könnt jetzt die Apexismaschine benutzen, die zu dem Amulett führt.\n\nDen Aufzeichnungen der Arakkoa zufolge befindet sie sich wahrscheinlich im Vergessenen Anzuversteck, im \"Schrein des Rabengotts\".", sourceObjective = "Aktiviert die Apexismaschine und bringt das Amulett von Rukhmar in Euren Besitz.", progress = "Habt Ihr das Amulett gefunden?", completion = "Es is' gut, dass wir vor den Arakkoa an das Ding gekomm'n sind.\n\nJones wird sich sehr dafür interessieren, da könnt Ihr Gift drauf nehm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[37994] = { id = 37994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Zauberfoliant: Die Barriere durchbrechen", description = "Ihr habt die Bestandteile gesammelt und einen \"arkanen Panzerknacker\" hergestellt.\nDieser Sprengsatz hat hoffentlich genug Wucht, um die Barriere zu zerstören.\n\nEs gibt nur einen Weg, das herauszufinden...", sourceObjective = "Zerstört die uralte Barriere unterhalb von Socrethars Klippe und nehmt den Foliant der namenlosen Leere an Euch.", progress = "Ich fühl' ziemlich üblen Voodoo von Euch ausgehen, Mann. \n\nDas muss von dem Buch komm'n!", completion = "Dieses Buch is' echt übel, Mann. Gut, dass wir es gefunden ham, bevor es in die falschen Hände gefall'n is'. \n\nIch geb es für Euch an Jones weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[37995] = { id = 37995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnfänger: Der Segen der Wildtiere", description = "Gronnfänger pulsiert nun mit der Kraft des Feuers und des Frosts. Es fehlt nur noch der Segen der Wildtiere, um der Waffe wieder ihre frühere Macht zu verleihen. Argoram glaubte, dass die Waffe dafür mit dem Blut der schwarzen Rylaks der Steinzornklippen geweiht werden muss. In seinem Tagebuch findet sich dazu folgender Eintrag:\n\n\"Oben auf den Steinzornklippen habe ich einen Altar gesehen, auf dem die Oger diesen uralten Kreaturen Opfergaben dargebracht haben. Vielleicht könnte ich so eine von ihnen anlocken.\"", sourceObjective = "Besiegt den uralten schwarzen Rylak und taucht Gronnfänger in sein Blut.\n\nBringt die Waffe zu Rokhan zurück, wenn Ihr sie mit Macht erfüllt habt, um Eure Belohnung zu erhalten.", progress = "Habt Ihr den Speer der Donnerfürsten?", completion = "Jones wird mehr als zufrieden sein, wenn er das sieht. \n\nHier is' die Belohnung, die er versprochen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[37996] = { id = 37996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schweigende Schädel: Den Greifer greifen", description = "Ihr habt alle Zutaten gefunden. Begebt Euch jetzt zum Lager des grinsenden Tolg in einer Höhle nicht weit von hier, um das Elixier zu brauen. \n\nSobald Ihr das Elixier getrunken habt, solltet Ihr mit den Verheerern in der Gegend kommunizieren können. Mit etwas Glück können sie Euch zu Schädelgreifer führen.\n\nFür seine Maske erwartet Euch eine gewaltige Belohnung.", sourceObjective = "Verwendet das Elixier des Lachenden Schädels, um Schädelgreifer zu finden, und nehmt den schweigenden Schädel an Euch.", progress = "Das muss der verfluchte Schädel sein, den Ihr da habt.", completion = "Für einen von den Lachenden Schädeln is' das 'ne ziemlich merkwürdige Maske. \n\nIch soll Euch diese Belohnung von Jones geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37997] = { id = 37997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von Argus: Wiedergeburt eines Kristalls", description = "Ihr habt alle Splitter gefunden. Fügt sie nun zusammen, um den Traum von Argus wiederherzustellen. Sucht die Maschine, die Maatun in seinem Tagebuch erwähnt; sie soll sich in einer Höhle oberhalb der Festung der Pein befinden.", sourceObjective = "Sucht die Maschine für die Kristallrekonstruktion und setzt mit ihrer Hilfe den Traum von Argus zusammen.", progress = "Habt Ihr den Kristall reparier'n können?", completion = "Unglaublich, Mann! Wenn ich's nich' besser wüßte, hätt' ich gedacht, das Ding war nie kaputt. \n\nHier ist die Belohnung von Jones, ich geb das an ihn weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[38000] = { id = 38000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 001 - Drowned Ruins" }
quests[38001] = { id = 38001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant im Feld!", description = "Wir wurden von diesen neuen Höllenorcs aufgehalten, aber am Ende werden wir siegen. Draka und ich haben es geschafft, einen kompletten Spähtrupp raus in den Dschungel zu schicken, um herauszufinden, worum wir uns noch kümmern müssen.\n\nIhr solltet die Späher aufsuchen, um zu verstehen, was hier auf uns zukommt.", sourceObjective = "Sammelt Berichte von den verschiedenen Spähern im Tanaandschungel.", completion = "Wir haben da einen ziemlichen Krieg an den Hacken. Wenigstens haben wir genügend Ziele zum Zuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38003] = { id = 38003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Killed Gaiju" }
