quests[38006] = { id = 38006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "delete me" }
quests[38008] = { id = 38008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße des Ruhms", description = "Die Horde will uns aus Ashran drängen, {name}. Das dürfen wir nicht zulassen. Marschiert zur Straße des Ruhms und vernichtet mindestens fünf von ihnen.", sourceObjective = "Chris Clarkie beim Sturmschild will, dass Ihr 5 Mitglieder der Horde auf der Straße des Ruhms tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[38009] = { id = 38009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Ruinen von Kra'nak" }
quests[38010] = { id = 38010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ruins of Kra'nak" }
quests[38014] = { id = 38014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich an den Drachen laben", description = "Ihr habt ihren Anführer umgebracht und sie sind hierhergekommen? Das ist nachvollziehbar. Diese Kreaturen haben es einzig und allein auf Magie abgesehen, und sie können sie über große Entfernungen hinweg wittern.\n\nOhne Anführer werden sie sehr schnell verdorren und sterben. In der Zwischenzeit bleibt uns nur, so viele von ihnen wie möglich zu töten, bevor sie sich die Drachen greifen!", sourceObjective = "Tötet 15 Verdorrte in der Azurschwingenrast.", progress = "Ja, {name}?", completion = "Das muss vorerst genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38015] = { id = 38015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zurück", description = "Diese vielen Verdorrten drohen, unsere ganze Brut auszulöschen!\n\nSchnell, {name}! Brecht einen Leykristall ab und heilt alle verwundeten Drachen, die Ihr auf dem Schlachtfeld finden könnt.\n\nIch werde tun, was ich kann, um diese Welplinge zu schützen.", sourceObjective = "Verwendet den strahlenden Leykristall oder Eure Heilzauber und Heilfähigkeiten, um die verwundeten Drachen zu heilen.", completion = "Gut gemacht. Ich habe gesehen, wie die anderen Drachen losgeflogen sind.\n\nUnd seht! Ihr habt Emmigosa gefunden!\n\nSie scheint Euch zu mögen, {name}. Ich vertraue darauf, dass Ihr auf sie aufpassen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[38020] = { id = 38020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel von Sha'naar" }
