quests[38035] = { id = 38035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Vorladung", sourceObjective = "Verwendet die königliche Vorladung und folgt Himmelsadmiralin Rogers durch das Portal zum Hafen von Sturmwind.", progress = "Können wir auf Euch zählen?", completion = "Danke für Eure Kooperation.", sourceObjectiveStatus = "unverified-source-field" }
quests[38036] = { id = 38036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub aus dem Himmel", description = "Geht es Euch gut? Sagt mal \"Ah\".\n\n<Mishka will Eure Zunge mit einem feuchten Zweig herunterdrücken.>\n\nTut mir leid... Wir benötigen hier dringend medizinische Vorräte. Die Krankenstation der Himmelsfeuer war gut ausgerüstet, aber jetzt ist alles in alle Winde verstreut.\n\nAlles, was Ihr aus dem Wrack bergen könnt, könnte Leben retten!", sourceObjective = "Sammelt 5 Erste-Hilfe-Kästen der Himmelsfeuer ein.", progress = "Habt Ihr etwas gefunden?", completion = "Gerade rechtzeitig! Ich wollte schon die Wunden der Gefangenen mit Blättern bandagieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38037] = { id = 38037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cache of Infernals" }
