quests[38043] = { id = 38043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Blutende Auge bluten" }
quests[38044] = { id = 38044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Blutende Auge bluten", description = "Das Blutende Auge stellt der Eisernen Horde in Tanaan eine beträchtliche Menge Verstärkungen zur Verfügung. Ausgehend von ihrer Heimat, Zeth'Gol, verfolgen sie unsere Späher, stören unsere Operationen und sammeln noch mehr Macht für Gul'dans Magie.\n\nWir sollten einen direkten Angriff auf Zeth'Gol ausführen, damit sie ihre Truppen aus dem Tal zurückziehen. Das sollte uns eine Atempause verschaffen... zumindest für eine Weile.", sourceObjective = "Greift das Blutende Auge in Zeth'Gol im Tanaandschungel an.", completion = "Ich habe schon gehört, dass sich die Jäger des Blutenden Auges nach Zeth'Gol zurückziehen. Das sollte uns in den anstehenden Kämpfen einen Vorteil verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38045] = { id = 38045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Blutende Auge bluten", description = "Das Blutende Auge stellt der Eisernen Horde in Tanaan eine beträchtliche Menge Verstärkungen zur Verfügung. Ausgehend von ihrer Heimat, Zeth'Gol, verfolgen sie unsere Späher, stören unsere Operationen und sammeln noch mehr Macht für Gul'dans Magie.\n\nWir sollten einen direkten Angriff auf Zeth'Gol ausführen, damit sie ihre Truppen aus dem Tal zurückziehen. Das sollte uns eine Atempause verschaffen... zumindest für eine Weile.", sourceObjective = "Greift das Blutende Auge in Zeth'Gol im Tanaandschungel an.", completion = "Gut gemacht, Kommandant! Das Blutende Auge schickt seine besten Krieg zur Verteidigung zurück nach Zeth'Gol.\n\nDas wird uns einen Vorteil verschaffen – zumindest vorübergehend.", sourceObjectiveStatus = "unverified-source-field" }
quests[38046] = { id = 38046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht an der Eisernen Front", description = "Unsere Truppen führen gerade einen vereinten Angriff an der Eisernen Front durch. Der Kampf dauert schon eine Weile an und die Verluste sind sehr hoch.\n\nMeldet Euch an der Eisernen Front und bietet Eure Unterstützung in diesem Krieg an. Ich habe keine Zweifel daran, dass Eure bloße Anwesenheit auf dem Schlachtfeld die Soldaten inspirieren und zum Sieg führen wird!", sourceObjective = "Unterstützt den Angriff der Allianz und der Horde an der Eisernen Front im Tanaandschungel.", completion = "Ich habe schon die Berichte von der Eisernen Front gehört, dass das Kriegsglück sich gewendet hat.\n\nBald wird die Eiserne Horde keinen Ort mehr finden, um sich zu verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[38047] = { id = 38047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht an der Eisernen Front", description = "Der Krieg gegen die Eiserne Horde geht weiter.\n\nNicht weit von hier kämpfen unsere Krieger an der Eisernen Front einen tödlichen Kampf gegen den Feind. Sie kämpfen entschlossen und unnachgiebig, aber sie haben auch große Verluste zu beklagen.\n\nBegebt Euch zur Eisernen Front und zeigt dem Feind, dass wir in diesem Krieg keinen Meter zurückweichen werden.\n\nZeigt ihnen, dass wir wie Wölfe kämpfen!", sourceObjective = "Unterstützt den Angriff der Allianz und der Horde an der Eisernen Front im Tanaandschungel.", completion = "Dank Eurer Unterstützung konnten wir unsere Position an der Eisernen Front behaupten. Schon bald werden Gul'dan und seine Eiserne Horde sich nirgends mehr verstecken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[38051] = { id = 38051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht an der Eisernen Front" }
quests[38052] = { id = 38052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geentert!", sourceObjective = "Schaltet 8 Fledermausreiter oder Todespirscher der Verlassenen aus.", progress = "Es wird keinen Frieden geben, solange diese Monster noch frei herumlaufen.", completion = "Keine Sorge wegen des Schiffs... das ist nur Holz und Metall.\n\nDie Himmelsfeuer wird so lange leben, wie wir weiterkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38053] = { id = 38053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff und Nachladen", description = "Wir müssen unsere Position SOFORT an die Allianzmarine durchgeben!\n\nIch baue einen neuen Transponder, um ein Notsignal senden zu können, aber dazu benötige ich eine Batterie aus der Kommunikationskonsole der Himmelsfeuer.\n\nDie Konsole findet Ihr auf der obersten Ebene des Schiffs... Ich hoffe nur, dass diese Untoten sie noch nicht in ihre kalten, knochigen Finger bekommen haben!", sourceObjective = "Nehmt Schreckensreiter Malwick die Transponderbatterie ab.", progress = "Ohne diese Batterie kann ich keinen neuen Transponder bauen!", completion = "Verflixte Flügelmutter!\n\nVerzeihung.\n\nDie ist ja fast so tot wie der Typ, dem Ihr sie abgenommen habt. Wir brauchen Saft... und zwar jede Menge. Und ich habe da so eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[38054] = { id = 38054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht an der Eisernen Front" }
quests[38057] = { id = 38057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Legion", sourceObjective = "Sucht nach den vermissten Dragonern der 7. Legion.", completion = "<Obwohl seine Augen geöffnet sind, reagiert der Soldat nicht auf Eure Anwesenheit. Um ihn herum sirrt ein elektrisches Feld.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38058] = { id = 38058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzableiter", description = "<Oberfunks winzige Hände bewegen sich wie der Blitz, während er Spulen und Röhren an dem Gerät befestigt und es dann in einen Fallschirmrucksack stopft.>\n\nLegt den an.\n\nGleich da oben am Hügel findet Ihr den Bug der Himmelsfeuer... und auch das riesige Nest Sturmdrachen, in das er hineingekracht ist! Wir können die Energie dieser Drachen nutzen, um den Transponder aufzuladen.\n\nDazu müsst Ihr sie natürlich etwas anstacheln, aber das Gerät sollte den Großteil der Energie einfangen.\n\nDas Risiko, dass Ihr dabei von Stromschlägen geröstet werdet, ist in einem akzeptablen Toleranzbereich!", sourceObjective = "Ladet den Transponder auf, indem Ihr die Blitzangriffe der Sturmdrachen absorbiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[38059] = { id = 38059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausend kleine Nadeln", description = "Argghh!\n\nIch halte das nicht aus. Das pikst wie tausend kleine Nadeln.\n\nSolche Kreaturen sind normalerweise kein Problem für die 7., aber auf ihre elektrischen Angriffe waren wir nicht vorbereitet. Bevor ich wusste, was passiert, war ich in einer Art statischem Feld gefangen und konnte keinen Muskel mehr bewegen. Und dann kamt Ihr vorbei.\n\nMeine Kameraden sind tiefer in die Höhle verschleppt worden. Holt sie da raus, bevor sie zu Welpenfutter verarbeitet werden!", sourceObjective = "Befreit 6 Dragoner der 7. Legion aus den statischen Feldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[38060] = { id = 38060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signalverstärkung", description = "Der Steuerbordpropeller der Himmelsfeuer ist auf den Klippen oberhalb unseres Lagers gelandet. Wir werden ihn als große Antenne verwenden, um unser Notrufsignal so weit zu senden, dass es selbst von Mekkadrills Wecker empfangen werden könnte!\n\nLeider wird es wohl aber auch ungewollte Aufmerksamkeit erregen.\n\nWir hier unten im Lager sind auf Feindkontakt eingestellt. Schickt das Signal los und macht Euch bereit, die Antenne zu verteidigen!", sourceObjective = "Verwendet den Rotor der Himmelsfeuer, um ein Notsignal zu senden, und haltet dann aus, bis Hilfe eintrifft.", completion = "Das Notsignal ist durchgekommen. Wir werden umgehend zur Grauen Wacht evakuiert.\n\nIch fürchte, dass Ihr Eure Mission vorerst ohne uns fortführen müsst. Wenn wir uns dort eingerichtet haben, werde ich Spähpatrouillen entsenden, um herauszufinden, wo sich die Aegis befindet.\n\nWenn wir die Legion besiegen wollen, müsst Ihr die Aegis von Aggramar unbedingt sicherstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38061] = { id = 38061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pridelord Meowl" }
